      const next = calmVisible({ loading, since: at.since, shownAt: at.shownAt, now, delay, min });
      if (next.visible && at.shownAt == null) at.shownAt = now;
      if (!next.visible) at.shownAt = null;
      setVisible(next.visible);
      if (next.wakeIn != null) timer = setTimeout(look, next.wakeIn);
    };
    look();
    return () => clearTimeout(timer);
  }, [loading, delay, min]);
  return visible;
}

import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import { Check, Copy } from "lucide-react";

import "./nxDetails.css";
import { announce } from "../nxAnnounce.js";
import { Button, Icon } from "../nxPrimitives.jsx";
import { calmVisible, meterFraction, numberCells, wheelRest, wheelTarget } from "./nxDetailsModel.js";

// Neyvia's details library (plan 17 A2): small moments that make the product feel finished.
// Each one has a design-manual entry (manuals/design.manual.json, chapter "details"), a
// design-lab specimen (lab/specimens/details-*.jsx) and its sources in
// docs/design/details-library.md. Motion uses the duration and spring tokens only; the
// global reduced-motion rule in nxTokens.css turns every transition here into a cut, and
// JS that would move something checks prefers-reduced-motion first (haptic below).
// Generated apps get this folder through the app template (details.manifest.json).

/** The press class: a 0.97 press on --nx-snappy for buttons that act (Emil Kowalski, MIT). */
export const PRESS = "nx-press";

const reducedMotion = () => typeof window !== "undefined" && Boolean(window.matchMedia?.("(prefers-reduced-motion: reduce)").matches);

/**
 * Haptic-like feedback on phones: a very short vibration where the browser supports it,
 * never on a mouse, never when the person asked for reduced motion. Returns true if it ran.
 */
export function haptic(kind = "tick") {
  try {
    if (typeof navigator === "undefined" || typeof navigator.vibrate !== "function") return false;
    if (!window.matchMedia?.("(pointer: coarse)").matches || reducedMotion()) return false;
    return navigator.vibrate(kind === "confirm" ? [8, 40, 12] : 8);
  } catch {
    return false;
  }
}

/* ---------- rolling number ---------- */

function Column({ digit, dir, fresh }) {
  const [state, setState] = useState(() => ({ pos: 10 + digit, snap: false }));
  const [born] = useState(fresh);
  const strip = useRef(null);
  const pos = useRef(10 + digit);

  useLayoutEffect(() => {
    const inBand = pos.current >= 10 && pos.current < 20;
    const to = wheelTarget(inBand ? pos.current : wheelRest(pos.current), digit, dir);
    if (to === pos.current) return;
    pos.current = to;
    setState({ pos: to, snap: !inBand });
  }, [digit]); // eslint-disable-line react-hooks/exhaustive-deps -- a change of direction alone must not move the wheel

  useLayoutEffect(() => {
    if (!state.snap) return undefined;
    void strip.current?.getBoundingClientRect(); // apply the jump before the transition comes back
    const frame = requestAnimationFrame(() => setState(current => ({ ...current, snap: false })));
    return () => cancelAnimationFrame(frame);
  }, [state.snap]);

  const onEnd = event => {
    if (event.target !== event.currentTarget || event.propertyName !== "transform") return;
    const rest = wheelRest(pos.current);
    if (rest === pos.current) return;
    pos.current = rest;
    setState({ pos: rest, snap: true });
  };

  return (
    <span className={`nx-roll-col${born ? " is-new" : ""}`}>
      <span ref={strip} className={`nx-roll-strip${state.snap ? " is-snap" : ""}`} style={{ "--nx-roll-p": state.pos }} onTransitionEnd={onEnd} />
    </span>
  );
}

/**
 * A number that rolls to its new value, one wheel per digit, the short way in the
 * direction the value moved. A screen reader hears the whole number once.
 */
export function RollingNumber({ value, decimals = 0, locale, prefix, suffix, className = "" }) { // prefix/suffix: plain strings
  const amount = Number.isFinite(value) ? value : 0;
  const previous = useRef(amount);
  const dir = amount >= previous.current ? 1 : -1;
  useEffect(() => { previous.current = amount; }, [amount]);
  const mounted = useRef(false);
  useEffect(() => { mounted.current = true; }, []);
  const { text, cells } = numberCells(amount, { decimals, locale });
  return (
    <span className={`nx-roll ${className}`}>
      <span className="nx-visually-hidden">{prefix}{text}{suffix}</span>
      {/* The faces are CSS-generated text: the page's text (and an agent reading it) holds the number once. */}
      <span className="nx-roll-face" aria-hidden="true">
        {prefix != null ? <span className="nx-roll-mark" data-c={prefix} /> : null}
        {cells.map(cell => cell.kind === "digit"
          ? <Column key={cell.key} digit={cell.digit} dir={dir} fresh={mounted.current} />
          : <span key={cell.key} className="nx-roll-mark" data-c={cell.char} />)}
        {suffix != null ? <span className="nx-roll-mark" data-c={suffix} /> : null}
      </span>
    </span>
  );
}

/* ---------- meter ---------- */

function useNow(active, ms) {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    if (!active) return undefined;
    const timer = setInterval(() => setNow(Date.now()), ms);
    return () => clearInterval(timer);
  }, [active, ms]);
  return now;
}

/**
 * A thin progress meter. With `value`/`max` it shows the real fraction; with `startedAt`
 * and `estimateMs` it creeps (fast, then slower) and never passes 90 % until `done`.
 * It fills with transform (no layout), on the drift spring. `decorative` hides it from
 * screen readers when the text beside it already says the same.
 */
export function Meter({ value, max = 1, done = false, startedAt, estimateMs, tone = "ok", label, decorative = false, className = "" }) {
  const estimating = !done && !Number.isFinite(value) && Number.isFinite(startedAt) && Number(estimateMs) > 0;
  const now = useNow(estimating, 500);
  const fraction = meterFraction({ value, max, done, startedAt, estimateMs, now }) ?? 0;
  const known = !estimating;
  // decorative: the words beside it already say the same (e.g. "Night Shift 3/5").
  const a11y = decorative ? { "aria-hidden": true } : {
    role: "progressbar", "aria-label": label, "aria-valuemin": 0, "aria-valuemax": 100,
    "aria-valuenow": known ? Math.round(fraction * 100) : undefined, "aria-valuetext": known ? undefined : "In progress",
  };
  return (
    <span {...a11y}
      className={`nx-meter is-${done ? "ok" : tone}${estimating ? " is-estimating" : ""} ${className}`}>
      <i style={{ "--nx-meter": fraction }} />
    </span>
  );
}

/* ---------- confirm in place ---------- */

const FOCUSABLE = "button, [href], [tabindex]";

/**
 * Ask "Delete this?" right where the button was, no dialog. `children(open)` renders the
 * trigger. Focus goes to Keep (the safe choice); Escape or a click elsewhere keeps; after
 * Keep focus returns to the trigger; after the action a screen reader hears `doneText`.
 */
export function ConfirmInPlace({ question, confirmLabel, keepLabel = "Keep", doneText, onConfirm, onKeep, children, defaultOpen = false, className = "" }) {
  const [open, setOpen] = useState(Boolean(defaultOpen));
  const group = useRef(null);
  const keep = useRef(null);
  const host = useRef(null);
  const refocus = useRef(false);
  const opener = useRef(0); // which of the trigger's controls opened it, to hand focus back on Keep

  const close = useCallback(confirmed => {
    setOpen(false);
    if (confirmed) {
      haptic("confirm");
      if (doneText) announce(doneText);
      onConfirm?.();
    } else {
      refocus.current = true;
      onKeep?.();
    }
  }, [doneText, onConfirm, onKeep]);

  useEffect(() => {
    if (open) { keep.current?.focus(); return undefined; }
    if (refocus.current) {
      refocus.current = false;
      const controls = [...(host.current?.querySelectorAll(FOCUSABLE) || [])];
      (controls[opener.current] || controls[0])?.focus();
    }
    return undefined;
  }, [open]);

  useEffect(() => {
    if (!open) return undefined;
    const outside = event => { if (!group.current?.contains(event.target)) close(false); };
    document.addEventListener("pointerdown", outside, true);
    return () => document.removeEventListener("pointerdown", outside, true);
  }, [open, close]);

  if (open) {
    return (
      <span ref={group} className={`nx-confirm ${className}`} role="group" aria-label={question}
        onKeyDown={event => { if (event.key === "Escape") { event.stopPropagation(); close(false); } }}>
        <span className="nx-confirm-q">{question}</span>
        <Button size="sm" variant="warn" className={PRESS} onClick={() => close(true)}>{confirmLabel}</Button>
        <Button ref={keep} size="sm" className={PRESS} onClick={() => close(false)}>{keepLabel}</Button>
      </span>
    );
  }
  const ask = () => {
    const controls = [...(host.current?.querySelectorAll(FOCUSABLE) || [])];
    opener.current = Math.max(0, controls.indexOf(document.activeElement));
    setOpen(true);
  };
  return <span ref={host} className="nx-confirm-host">{children(ask)}</span>;
}

/* ---------- strike ---------- */

/** Text that gets a line drawn through it when `on` turns true (a done task), per line. */
export function Strike({ on, children }) {
  return <span className={`nx-strike${on ? " is-on" : ""}`}>{children}</span>;
}

/* ---------- copy ---------- */

/** Copy with a result: state is idle | done | failed for `resetMs`, announced either way. */
export function useCopy({ doneLabel = "Copied", failedLabel = "Copy failed", resetMs = 1600 } = {}) {
  const [state, setState] = useState("idle");
  const timer = useRef(0);
  useEffect(() => () => clearTimeout(timer.current), []);
  const copy = useCallback(async text => {
    clearTimeout(timer.current);
    let next = "failed";
    try {
      if (!navigator.clipboard?.writeText) throw new Error("no clipboard");
      await navigator.clipboard.writeText(String(text ?? ""));
      next = "done";
      haptic("tick");
    } catch { /* the label says it failed */ }
    setState(next);
    announce(next === "done" ? doneLabel : failedLabel);
    timer.current = setTimeout(() => setState("idle"), resetMs);
    return next === "done";
  }, [doneLabel, failedLabel, resetMs]);
  return [state, copy];
}

/**
 * Copy button whose icon turns into a drawn check for a moment. Icon only by default
 * (`label` is its name); `showLabel` also writes the word, which changes to "Copied".
 */
export function CopyButton({ text, label = "Copy", doneLabel = "Copied", failedLabel = "Copy failed", showLabel = false, size = "sm", className = "" }) {
  const [state, copy] = useCopy({ doneLabel, failedLabel });
  const word = state === "done" ? doneLabel : state === "failed" ? failedLabel : label;
  return (
    <button type="button" className={`nx-copybtn is-${size} is-${state} ${PRESS} ${className}`}
      aria-label={showLabel ? undefined : label} title={word} onClick={() => void copy(text)}>
      <span className="nx-copybtn-icons" aria-hidden="true">
        <Icon as={Copy} size={size === "xs" ? 12 : 14} className="nx-copybtn-copy" />
        <Icon as={Check} size={size === "xs" ? 12 : 14} className="nx-copybtn-check" />
      </span>
      {showLabel ? <span className="nx-copybtn-label">{word}</span> : null}
    </button>
  );
}

/* ---------- empty state ---------- */

/**
 * An honest empty state: what is (not) here, and one way forward. tone: first (nothing
 * yet), filtered (nothing matches; the action clears the filter), done (all finished).
 */
export function EmptyState({ icon, title, hint, action, tone = "first", className = "" }) {
  return (
    <div className={`nx-blank is-${tone} ${className}`}>
      {icon ? <span className="nx-blank-mark"><Icon as={icon} size={18} /></span> : null}
      {title ? <strong className="nx-blank-title">{title}</strong> : null}
      {hint ? <p className="nx-blank-hint">{hint}</p> : null}
      {action ? <Button size="sm" variant="outline" icon={action.icon} className={PRESS} onClick={action.onClick}>{action.label}</Button> : null}
    </div>
  );
}

/* ---------- calm loading ---------- */

/**
 * True while a loading state should show: only after `delay` ms of waiting (a fast load
 * shows nothing), and then for at least `min` ms (it never flashes on and off).
 */
export function useCalmLoading(loading, { delay = 240, min = 480 } = {}) {
  const [visible, setVisible] = useState(false);
  const marks = useRef({ since: null, shownAt: null });
  useEffect(() => {
    const at = marks.current;
    if (loading && at.since == null) at.since = Date.now();
    if (!loading) at.since = null;
    let timer = 0;
    const look = () => {
      const now = Date.now();
      const next = calmVisible({ loading, since: at.since, shownAt: at.shownAt, now, delay, min });
      if (next.visible && at.shownAt == null) at.shownAt = now;
      if (!next.visible) at.shownAt = null;
      setVisible(next.visible);
      if (next.wakeIn != null) timer = setTimeout(look, next.wakeIn);
    };
    look();
    return () => clearTimeout(timer);
  }, [loading, delay, min]);
  return visible;
}

// Neyvia details for generated apps (plan 17 A2): the same small moments as Neyvia's own
// React details (../nxDetails.jsx), as plain DOM functions with no framework and no
// dependencies, so a web/PWA app made by `neyvia app new web` gets them from its first
// commit. Copy this folder as `details/` (details.manifest.json says which files), link
// details.css, import from details.js. The pure logic is shared with Neyvia (model.js).
// Sources and credits: docs/design/details-library.md.

import { calmVisible, meterFraction, numberCells, wheelRest, wheelTarget } from "./model.js";

const reduced = () => Boolean(globalThis.matchMedia?.("(prefers-reduced-motion: reduce)").matches);

/** A very short vibration on touch phones; never on a mouse or with reduced motion. */
export function haptic(kind = "tick") {
  try {
    if (typeof navigator.vibrate !== "function" || !matchMedia("(pointer: coarse)").matches || reduced()) return false;
    return navigator.vibrate(kind === "confirm" ? [8, 40, 12] : 8);
  } catch {
    return false;
  }
}

let live = null;
/** Read a short sentence to screen readers (one polite live region per page). */
export function announce(text) {
  if (!text) return;
  if (!live?.isConnected) {
    live = document.createElement("div");
    live.className = "nxd-sr";
    live.setAttribute("role", "status");
    live.setAttribute("aria-live", "polite");
    document.body.append(live);
  }
  live.textContent = "";
  setTimeout(() => { live.textContent = String(text); }, 60);
}

const el = (tag, className, attrs = {}) => {
  const node = document.createElement(tag);
  if (className) node.className = className;
  for (const [key, value] of Object.entries(attrs)) if (value != null) node.setAttribute(key, value);
  return node;
};

/* ---------- rolling number ---------- */

const wheels = new WeakMap();

/**
 * Show `value` in `host`, rolling each digit the short way in the direction it moved.
 * Call again with the new value. The digits are CSS-generated, so the page text holds
 * the number once (for screen readers and for agents reading the app).
 */
export function rollingNumber(host, value, { decimals = 0, locale, suffix = "" } = {}) {
  let state = wheels.get(host);
  if (!state) {
    host.classList.add("nxd-roll");
    host.textContent = "";
    const sr = el("span", "nxd-sr");
    const face = el("span", "nxd-roll-face", { "aria-hidden": "true" });
    host.append(sr, face);
    state = { sr, face, cols: new Map(), last: null };
    wheels.set(host, state);
  }
  const amount = Number.isFinite(value) ? value : 0;
  const dir = state.last == null || amount >= state.last ? 1 : -1;
  const { text, cells } = numberCells(amount, { decimals, locale });
  state.sr.textContent = text + suffix;
  const keep = new Set();
  const nodes = [];
  for (const cell of cells) {
    keep.add(cell.key);
    let col = state.cols.get(cell.key);
    if (cell.kind === "mark") {
      if (!col) { col = { node: el("span", "nxd-roll-mark") }; state.cols.set(cell.key, col); }
      col.node.dataset.c = cell.char;
    } else {
      if (!col) {
        const node = el("span", `nxd-roll-col${state.last == null ? "" : " is-new"}`);
        const strip = el("span", "nxd-roll-strip");
        node.append(strip);
        col = { node, strip, pos: 10 + cell.digit };
        strip.style.setProperty("--nxd-roll-p", col.pos);
        strip.addEventListener("transitionend", event => {
          if (event.propertyName !== "transform") return;
          const rest = wheelRest(col.pos);
          if (rest === col.pos) return;
          col.pos = rest;
          strip.classList.add("is-snap");
          strip.style.setProperty("--nxd-roll-p", rest);
          void strip.getBoundingClientRect();
          strip.classList.remove("is-snap");
        });
        state.cols.set(cell.key, col);
      } else {
        const inBand = col.pos >= 10 && col.pos < 20;
        const to = wheelTarget(inBand ? col.pos : wheelRest(col.pos), cell.digit, dir);
        if (to !== col.pos) {
          if (!inBand) col.strip.classList.add("is-snap");
          col.pos = to;
          col.strip.style.setProperty("--nxd-roll-p", to);
          if (!inBand) { void col.strip.getBoundingClientRect(); col.strip.classList.remove("is-snap"); }
        }
      }
    }
    nodes.push(col.node);
  }
  if (suffix) {
    state.suffix ||= el("span", "nxd-roll-mark");
    state.suffix.dataset.c = suffix;
    nodes.push(state.suffix);
  }
  for (const [key, col] of state.cols) if (!keep.has(key)) state.cols.delete(key);
  // Move only what changed place: a column taken out of the page loses its running roll.
  for (const child of [...state.face.children]) if (!nodes.includes(child)) child.remove();
  nodes.forEach((node, index) => { if (state.face.children[index] !== node) state.face.insertBefore(node, state.face.children[index] || null); });
  state.last = amount;
}

/* ---------- meter ---------- */

const meters = new WeakMap();

/**
 * A thin progress meter in `host`. Pass {value, max} for real progress, or {startedAt,
 * estimateMs} for work with only an estimate (it creeps and stays under 90 % until done).
 */
export function meter(host, { value, max = 1, done = false, startedAt, estimateMs, tone = "ok", label } = {}) {
  let state = meters.get(host);
  if (!state) {
    host.classList.add("nxd-meter");
    host.setAttribute("role", "progressbar");
    host.setAttribute("aria-valuemin", "0");
    host.setAttribute("aria-valuemax", "100");
    const fill = el("i");
    host.replaceChildren(fill);
    state = { fill, timer: 0 };
    meters.set(host, state);
  }
  clearInterval(state.timer);
  if (label) host.setAttribute("aria-label", label);
  host.dataset.tone = done ? "ok" : tone;
  const estimating = !done && !Number.isFinite(value) && Number.isFinite(startedAt) && Number(estimateMs) > 0;
  const paint = () => {
    const fraction = meterFraction({ value, max, done, startedAt, estimateMs, now: Date.now() }) ?? 0;
    state.fill.style.setProperty("--nxd-meter", fraction);
    if (estimating) { host.removeAttribute("aria-valuenow"); host.setAttribute("aria-valuetext", "In progress"); }
    else { host.setAttribute("aria-valuenow", String(Math.round(fraction * 100))); host.removeAttribute("aria-valuetext"); }
  };
  paint();
  if (estimating) state.timer = setInterval(paint, 500);
}

/* ---------- confirm in place ---------- */

/**
 * Make `trigger` ask "Delete this?" right where it is. Focus goes to Keep; Escape or a
 * click elsewhere keeps; Delete calls onConfirm and announces doneText.
 */
export function confirmInPlace(trigger, { question, confirmLabel = "Delete", keepLabel = "Keep", doneText, onConfirm, onKeep } = {}) {
  let group = null;
  const close = confirmed => {
    if (!group) return;
    document.removeEventListener("pointerdown", outside, true);
    group.remove();
    group = null;
    trigger.hidden = false;
    if (confirmed) { haptic("confirm"); if (doneText) announce(doneText); onConfirm?.(); }
    else { trigger.focus(); onKeep?.(); }
  };
  const outside = event => { if (group && !group.contains(event.target)) close(false); };
  trigger.addEventListener("click", () => {
    if (group) return;
    group = el("span", "nxd-confirm", { role: "group", "aria-label": question });
    const ask = el("span", "nxd-confirm-q");
    ask.textContent = question;
    const yes = el("button", "nxd-btn is-danger", { type: "button" });
    yes.textContent = confirmLabel;
    const no = el("button", "nxd-btn", { type: "button" });
    no.textContent = keepLabel;
    yes.addEventListener("click", () => close(true));
    no.addEventListener("click", () => close(false));
    group.addEventListener("keydown", event => { if (event.key === "Escape") { event.stopPropagation(); close(false); } });
    group.append(ask, yes, no);
    trigger.after(group);
    trigger.hidden = true;
    no.focus();
    document.addEventListener("pointerdown", outside, true);
  });
  return { close: () => close(false) };
}

/* ---------- copy ---------- */

const COPY_ICON = '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>';
const CHECK_ICON = '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 6 9 17l-5-5"/></svg>';

/**
 * Turn `button` into a copy button: its icon becomes a drawn check when the copy worked,
 * and it says "Copy failed" when the clipboard refused. `text` is a string or a function.
 */
export function copyButton(button, text, { label = "Copy", doneLabel = "Copied", failedLabel = "Copy failed", showLabel = false } = {}) {
  button.type = "button";
  button.classList.add("nxd-copy", "nxd-press");
  button.innerHTML = `<span class="nxd-copy-icons">${COPY_ICON.replace("<svg", '<svg class="nxd-copy-a"')}${CHECK_ICON.replace("<svg", '<svg class="nxd-copy-b"')}</span>`;
  const word = el("span", "nxd-copy-label");
  if (showLabel) { word.textContent = label; button.append(word); } else button.setAttribute("aria-label", label);
  button.title = label;
  let timer = 0;
  button.addEventListener("click", async () => {
    clearTimeout(timer);
    let state = "failed";
    try {
      await navigator.clipboard.writeText(String(typeof text === "function" ? text() : text));
      state = "done";
      haptic("tick");
    } catch { /* the label says it failed */ }
    button.dataset.state = state;
    button.title = state === "done" ? doneLabel : failedLabel;
    if (showLabel) word.textContent = button.title;
    announce(button.title);
    timer = setTimeout(() => { button.dataset.state = "idle"; button.title = label; if (showLabel) word.textContent = label; }, 1600);
  });
}

/* ---------- strike, empty state, calm loading ---------- */

/** Cross out `node`'s text (a finished task); the line draws in. */
export function strike(node, on) {
  node.classList.add("nxd-strike");
  node.classList.toggle("is-on", Boolean(on));
}

/**
 * An honest empty state: what is (not) here and one way forward.
 * tone: first | filtered | done. action: {label, onClick}.
 */
export function emptyState({ title, hint, action, tone = "first" } = {}) {
  const box = el("div", `nxd-empty is-${tone}`);
  if (title) { const node = el("strong"); node.textContent = title; box.append(node); }
  if (hint) { const node = el("p"); node.textContent = hint; box.append(node); }
  if (action) {
    const button = el("button", "nxd-btn nxd-press", { type: "button" });
    button.textContent = action.label;
    button.addEventListener("click", action.onClick);
    box.append(button);
  }
  return box;
}

/**
 * Show a loading state only for waits long enough to notice (after `delay` ms), and then
 * for at least `min` ms. Call start() when loading begins and stop() when it ends.
 */
export function calmLoading({ show, hide, delay = 240, min = 480 }) {
  const at = { since: null, shownAt: null, loading: false, visible: false, timer: 0 };
  const look = () => {
    clearTimeout(at.timer);
    const now = Date.now();
    const next = calmVisible({ loading: at.loading, since: at.since, shownAt: at.shownAt, now, delay, min });
    if (next.visible && at.shownAt == null) at.shownAt = now;
    if (!next.visible) at.shownAt = null;
    if (next.visible !== at.visible) { at.visible = next.visible; (next.visible ? show : hide)?.(); }
    if (next.wakeIn != null) at.timer = setTimeout(look, next.wakeIn);
  };
  return {
    start() { at.loading = true; at.since ??= Date.now(); look(); },
    stop() { at.loading = false; at.since = null; look(); },
  };
}

/* Neyvia details for generated apps (details.js). Self-contained: the tokens below are
   Neyvia's (Forest at night, Morning by day) and an app may override any of them on
   :root. Motion stays in Neyvia's 180-320 ms band and becomes a cut with reduced motion. */

:root {
  --nxd-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --nxd-spring-snappy: linear(0, 0.058, 0.179, 0.322, 0.446, 0.575, 0.685, 0.774, 0.843, 0.895, 0.933, 0.957, 0.976, 0.988, 0.996, 1.001, 1.003, 1.004, 1.004, 1.003, 1.002, 1.001, 1);
  --nxd-spring-settle: linear(0, 0.047, 0.154, 0.287, 0.427, 0.571, 0.686, 0.782, 0.859, 0.917, 0.96, 0.989, 1.008, 1.019, 1.025, 1.026, 1.024, 1.021, 1.018, 1.014, 1.011, 1.008, 1.005, 1.004, 1.002, 1.001, 1);
  --nxd-fast: 180ms;
  --nxd-med: 200ms;
  --nxd-snappy: 220ms;
  --nxd-settle: 320ms;
  --nxd-text: var(--nx-text);
  --nxd-muted: var(--nx-text-2);
  --nxd-line: color-mix(in srgb, var(--nx-line-strong) 16%, transparent);
  --nxd-hover: color-mix(in srgb, var(--nx-raised) 7%, transparent);
  --nxd-raised: var(--nx-bg);
  --nxd-ok: var(--nx-accent);
  --nxd-running: var(--nx-state-running);
  --nxd-danger: var(--nx-red);
  --nxd-danger-soft: color-mix(in srgb, var(--nx-red) 14%, transparent);
  --nxd-accent-soft: color-mix(in srgb, var(--nx-accent) 13%, transparent);
  --nxd-track: color-mix(in srgb, var(--nx-raised) 10%, transparent);
}
@media (prefers-color-scheme: light) {
  :root {
    /* Morning (plan 19 R3): Neyvia's light theme, forest shade instead of brown. */
    --nxd-text: var(--nx-muted);
    --nxd-muted: var(--nx-muted);
    --nxd-line: color-mix(in srgb, var(--nx-line-strong) 18%, transparent);
    --nxd-hover: color-mix(in srgb, var(--nx-bg) 6%, transparent);
    --nxd-raised: var(--nx-raised);
    --nxd-ok: var(--nx-accent);
    --nxd-running: var(--nx-state-running);
    --nxd-danger: var(--nx-red);
    --nxd-danger-soft: color-mix(in srgb, var(--nx-red) 10%, transparent);
    --nxd-accent-soft: color-mix(in srgb, var(--nx-accent) 11%, transparent);
    --nxd-track: color-mix(in srgb, var(--nx-bg) 10%, transparent);
  }
}

.nxd-sr { position: absolute; width: 1px; height: 1px; margin: calc(-1 * var(--nx-space-1)); padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }

/* press: a 0.97 press, never from nothing */
.nxd-press { transition: transform var(--nxd-snappy) var(--nxd-spring-snappy), background-color var(--nxd-fast) var(--nxd-ease), color var(--nxd-fast) var(--nxd-ease); }
.nxd-press:active:not(:disabled) { transform: scale(0.97); }

.nxd-btn {
  font: inherit; font-size: var(--nx-fs-md); height: 2em; padding: 0 var(--nx-space-12); border: 0; border-radius: var(--nx-r-pill); cursor: pointer;
  color: var(--nxd-text); background: transparent; box-shadow: inset 0 0 0 var(--nx-stroke) var(--nxd-line);
}
