/* ---------- press (Emil Kowalski: scale 0.97 on press, never from nothing) ---------- */
.nx :is(.nx-btn, .nx-iconbtn, .nx-copybtn).nx-press {
  transition: transform var(--nx-snappy) var(--nx-spring-snappy), background var(--nx-fast) var(--nx-ease),
    color var(--nx-fast) var(--nx-ease), box-shadow var(--nx-fast) var(--nx-ease), opacity var(--nx-fast) var(--nx-ease);
}
.nx :is(.nx-btn, .nx-iconbtn, .nx-copybtn).nx-press:active:not(:disabled) { transform: scale(0.97); }

/* ---------- rolling number ---------- */
.nx .nx-roll { display: inline-flex; font-variant-numeric: tabular-nums; }
.nx .nx-roll-face { --nx-roll-h: 1.3em; display: inline-flex; align-items: baseline; }
.nx .nx-roll-col {
  position: relative; display: inline-grid; line-height: var(--nx-roll-h); overflow: hidden; /* a grid's baseline stays its first row's, unlike a clipped inline-block */
  /* Faces fade through the air above and below, so a resting digit stays solid (mask alpha only). */
  mask-image: linear-gradient(to bottom, transparent, var(--nx-bg) 24%, var(--nx-bg) 76%, transparent);
}
.nx .nx-roll-col::before { content: "0"; visibility: hidden; } /* sizer: one digit wide, and the baseline */
