/* Conductor (NxConductor): goals on the left; the chosen goal's routed task
   tree on the right, read left to right in the order work can happen, with
   the checks and receipts beside it. */

.nx .nx-cd { flex: 1 1 auto; min-height: 0; display: flex; background: var(--nx-panel); }
.nx .nx-cd-list { flex: 0 0 260px; display: flex; flex-direction: column; gap: var(--nx-space-6); padding: var(--nx-space-12) var(--nx-space-10); box-shadow: inset calc(-1 * var(--nx-stroke)) 0 0 var(--nx-line); }
.nx .nx-cd-list-head { display: flex; align-items: center; gap: var(--nx-space-4); margin-bottom: var(--nx-space-6); }
.nx .nx-cd-list-head > .nx-btn { margin-right: auto; }
.nx .nx-cd-list > .nx-btn { align-self: flex-start; }
.nx .nx-cd-card { display: grid; gap: var(--nx-space-6); padding: var(--nx-space-10); border-radius: var(--nx-r-lg); text-align: left; box-shadow: inset 0 0 0 var(--nx-stroke) var(--nx-line); transition: background var(--nx-fast) var(--nx-ease); }
.nx .nx-cd-card:hover { background: var(--nx-hover); }
.nx .nx-cd-card.is-on { background: var(--nx-active); box-shadow: inset 0 0 0 var(--nx-stroke) color-mix(in srgb, var(--nx-accent-hi) 45%, transparent); }
.nx .nx-cd-card-goal { font-weight: 500; color: var(--nx-text); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; overflow-wrap: anywhere; }
.nx .nx-cd-card-meta { display: flex; align-items: center; justify-content: space-between; gap: var(--nx-space-6); font-size: var(--nx-fs-xs); color: var(--nx-muted); font-variant-numeric: tabular-nums; }
.nx .nx-cd-card-bar, .nx .nx-cd-progress { position: relative; height: 3px; border-radius: var(--nx-r-xxs); background: var(--nx-line-strong); overflow: hidden; flex: none; }
.nx .nx-cd-card-bar > span, .nx .nx-cd-progress > span { position: absolute; inset: 0; background: var(--nx-green); transform-origin: 0 50%; transition: transform var(--nx-drift) var(--nx-spring-drift); }
.nx .nx-cd-switch { margin-top: auto; display: inline-flex; align-items: center; gap: var(--nx-space-4); align-self: flex-start; padding: var(--nx-space-4) var(--nx-space-6); border-radius: var(--nx-r-sm); font-size: var(--nx-fs-sm); color: var(--nx-accent-text); }
.nx .nx-cd-switch:hover { background: var(--nx-hover); }
.nx .nx-cd-empty { margin: var(--nx-space-8) var(--nx-space-4); color: var(--nx-muted); font-size: var(--nx-fs-sm); line-height: 1.5; }
.nx .nx-cd-empty.is-big { margin: auto; display: grid; justify-items: center; gap: var(--nx-space-12); max-width: 360px; text-align: center; --ny-tree-ink: var(--nx-text-2); --ny-tree-leaf: var(--nx-green); --ny-tree-sun: var(--nx-amber); }

.nx .nx-cd-phase { display: inline-flex; align-items: center; gap: var(--nx-space-5); padding: 0 var(--nx-space-8); border-radius: var(--nx-r-pill); line-height: 20px; font-size: var(--nx-fs-xs); color: var(--nx-text-2); box-shadow: inset 0 0 0 var(--nx-stroke) var(--nx-line-strong); white-space: nowrap; }
.nx .nx-cd-phase.is-live { color: var(--nx-state-running-text); box-shadow: inset 0 0 0 var(--nx-stroke) color-mix(in srgb, var(--nx-amber) 45%, transparent); }
.nx .nx-cd-phase.is-gold { color: var(--nx-state-needs); box-shadow: inset 0 0 0 var(--nx-stroke) color-mix(in srgb, var(--nx-gold) 45%, transparent); }
.nx .nx-cd-phase.is-green { color: var(--nx-state-ok); }
.nx .nx-cd-phase.is-red { color: var(--nx-state-error); }

.nx .nx-cd-main { flex: 1 1 auto; min-width: 0; min-height: 0; display: flex; flex-direction: column; position: relative; container-type: inline-size; }
.nx .nx-cd-view { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; gap: var(--nx-space-10); padding: var(--nx-space-16) var(--nx-space-18) 0; }
.nx .nx-cd-head { display: flex; align-items: flex-start; gap: var(--nx-space-8); flex-wrap: wrap; }
.nx .nx-cd-actions { display: flex; align-items: center; gap: var(--nx-space-6); flex-wrap: wrap; }
.nx .nx-cd-head-main { flex: 1 1 280px; min-width: 0; display: grid; gap: var(--nx-space-4); }
.nx .nx-cd-head h2 { font-size: var(--nx-fs-lg); font-weight: 600; line-height: 1.35; color: var(--nx-text); display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; overflow-wrap: anywhere; }
.nx .nx-cd-meta { display: inline-flex; align-items: center; gap: var(--nx-space-5); font-size: var(--nx-fs-xs); color: var(--nx-muted); font-family: var(--nx-mono); overflow-wrap: anywhere; }
.nx .nx-cd-banner { display: flex; align-items: flex-start; gap: var(--nx-space-10); padding: var(--nx-space-10) var(--nx-space-12); border-radius: var(--nx-r-lg); font-size: var(--nx-fs-sm); line-height: 1.45; color: var(--nx-text); }
.nx .nx-cd-banner > .nx-icon { flex: none; margin-top: var(--nx-space-1); }
.nx .nx-cd-banner.is-needs { background: var(--nx-gold-soft); box-shadow: inset 0 0 0 var(--nx-stroke) color-mix(in srgb, var(--nx-gold) 40%, transparent); }
.nx .nx-cd-banner.is-needs > .nx-icon { color: var(--nx-state-needs); }
.nx .nx-cd-banner.is-bad { background: var(--nx-red-soft); }
.nx .nx-cd-banner.is-bad > .nx-icon { color: var(--nx-state-error); }
.nx .nx-cd-error { color: var(--nx-state-error); font-size: var(--nx-fs-sm); overflow-wrap: anywhere; }
.nx .nx-cd-error.is-top { padding: var(--nx-space-10) var(--nx-space-18) 0; }
.nx .nx-cd-counts { font-size: var(--nx-fs-xs); color: var(--nx-muted); font-variant-numeric: tabular-nums; }
.nx .nx-cd-worker { display: flex; align-items: center; gap: var(--nx-space-7); font-size: var(--nx-fs-xs); color: var(--nx-muted); line-height: 1.45; }
.nx .nx-cd-worker .nx-dot { flex: none; }

.nx .nx-cd-body { flex: 1 1 auto; min-height: 0; display: flex; gap: var(--nx-space-14); padding-bottom: var(--nx-space-14); }
.nx .nx-cd-tree { flex: 1 1 auto; min-width: 0; display: flex; gap: var(--nx-space-14); align-items: flex-start; padding: var(--nx-space-2) var(--nx-space-2) var(--nx-space-8); overflow: auto; }
.nx .nx-cd-level { flex: 0 0 210px; display: grid; gap: var(--nx-space-8); }
.nx .nx-cd-level-label { font-size: var(--nx-fs-xs); color: var(--nx-muted); }
.nx .nx-cd-task {
  display: grid; gap: var(--nx-space-5); padding: var(--nx-space-10); border-radius: var(--nx-r-lg); text-align: left; background: var(--nx-raised);
  box-shadow: var(--nx-card-shadow); transition: box-shadow var(--nx-fast) var(--nx-ease), translate var(--nx-snappy) var(--nx-spring-snappy);
}
.nx .nx-cd-task:hover { translate: 0 -1px; }
.nx .nx-cd-task.is-selected { box-shadow: 0 0 0 var(--nx-stroke-icon) var(--nx-accent-hi), var(--nx-card-shadow); }
.nx .nx-cd-task.is-running { box-shadow: 0 0 0 var(--nx-stroke) color-mix(in srgb, var(--nx-amber) 50%, transparent), var(--nx-card-shadow); }
.nx .nx-cd-task.is-needs { box-shadow: 0 0 0 var(--nx-stroke) color-mix(in srgb, var(--nx-gold) 60%, transparent), var(--nx-card-shadow); }
.nx .nx-cd-task.is-failed { box-shadow: 0 0 0 var(--nx-stroke) color-mix(in srgb, var(--nx-red) 50%, transparent), var(--nx-card-shadow); }
.nx .nx-cd-task .ny-tree { --ny-tree-ink: var(--nx-text-2); --ny-tree-leaf: var(--nx-green); --ny-tree-sun: var(--nx-amber); }
.nx .nx-cd-task-top { display: flex; align-items: center; gap: var(--nx-space-6); }
.nx .nx-cd-task-route { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: var(--nx-fs-xs); color: var(--nx-muted); }
.nx .nx-cd-task-title { font-weight: 500; color: var(--nx-text); display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.nx .nx-cd-task-note { font-size: var(--nx-fs-xs); color: var(--nx-muted); font-variant-numeric: tabular-nums; }
.nx .nx-cd-task-note.is-needs { color: var(--nx-state-needs); }
.nx .nx-cd-planning { margin: var(--nx-space-24) auto; display: grid; justify-items: center; gap: var(--nx-space-10); color: var(--nx-muted); font-size: var(--nx-fs-sm); --ny-tree-ink: var(--nx-text-2); --ny-tree-leaf: var(--nx-green); --ny-tree-sun: var(--nx-amber); }

.nx .nx-cd-detail { flex: 0 0 320px; min-width: 0; display: flex; flex-direction: column; gap: var(--nx-space-10); padding: var(--nx-space-12); border-radius: var(--nx-r-lg); background: var(--nx-raised); box-shadow: var(--nx-card-shadow); }
.nx .nx-cd-detail > header { display: flex; align-items: center; gap: var(--nx-space-7); }
.nx .nx-cd-detail > header strong { flex: 1 1 auto; min-width: 0; font-weight: 600; color: var(--nx-text); overflow-wrap: anywhere; }
.nx .nx-cd-detail > header span { font-size: var(--nx-fs-xs); color: var(--nx-muted); }
.nx .nx-cd-detail h4 { font-size: var(--nx-fs-sm); font-weight: 600; color: var(--nx-text); }
.nx .nx-cd-facts, .nx .nx-cd-receipt dl { display: grid; gap: var(--nx-space-4); margin: 0; font-size: var(--nx-fs-sm); }
.nx .nx-cd-facts > div, .nx .nx-cd-receipt dl > div { display: grid; grid-template-columns: 64px minmax(0, 1fr); gap: var(--nx-space-8); }
.nx .nx-cd-facts dt, .nx .nx-cd-receipt dt { color: var(--nx-muted); }
.nx .nx-cd-facts dd, .nx .nx-cd-receipt dd { margin: 0; color: var(--nx-text-2); overflow-wrap: anywhere; }
.nx .nx-cd-detail .is-mono, .nx .nx-cd-muted .is-mono { font-family: var(--nx-mono); font-size: var(--nx-fs-xs); }
