.nx .nx-cd-reply { margin: 0; max-height: 220px; padding: var(--nx-space-8) var(--nx-space-10); border-radius: var(--nx-r); background: var(--nx-raised-2); font-family: var(--nx-mono); font-size: var(--nx-fs-xs); line-height: 1.5; color: var(--nx-text-2); white-space: pre-wrap; overflow-wrap: anywhere; }
.nx .nx-cd-prompt { font-size: var(--nx-fs-sm); line-height: 1.5; color: var(--nx-text-2); white-space: pre-wrap; overflow-wrap: anywhere; }
.nx .nx-cd-needs { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: var(--nx-space-8) var(--nx-space-10); padding: var(--nx-space-10); border-radius: var(--nx-r); background: var(--nx-gold-soft); font-size: var(--nx-fs-sm); color: var(--nx-text); }
.nx .nx-cd-needs > .nx-icon { color: var(--nx-state-needs); margin-top: var(--nx-space-1); }
.nx .nx-cd-needs > .nx-btn { grid-column: 2; justify-self: start; }
.nx .nx-cd-checks { display: grid; gap: var(--nx-space-8); margin: 0; padding: 0; list-style: none; font-size: var(--nx-fs-sm); color: var(--nx-text-2); }
.nx .nx-cd-checks li { display: flex; gap: var(--nx-space-7); align-items: flex-start; }
.nx .nx-cd-checks li > span { display: grid; gap: var(--nx-space-3); min-width: 0; overflow-wrap: anywhere; }
.nx .nx-cd-checks small { font-size: var(--nx-fs-xs); color: var(--nx-muted); line-height: 1.45; }
.nx .nx-cd-checks .nx-icon { margin-top: var(--nx-space-2); flex: none; color: var(--nx-muted); }
.nx .nx-cd-checks .is-ok .nx-icon { color: var(--nx-state-ok); }
.nx .nx-cd-checks .is-bad .nx-icon { color: var(--nx-state-error); }
.nx .nx-cd-turns { display: grid; gap: var(--nx-space-2); margin: 0; padding: 0; list-style: none; }
.nx .nx-cd-turns button { width: 100%; display: grid; grid-template-columns: auto minmax(0, 1fr); gap: var(--nx-space-2) var(--nx-space-8); align-items: center; padding: var(--nx-space-6) var(--nx-space-8); border-radius: var(--nx-r-sm); text-align: left; font-size: var(--nx-fs-sm); color: var(--nx-text-2); }
.nx .nx-cd-turns button:hover:not(:disabled) { background: var(--nx-hover); }
.nx .nx-cd-turns small { grid-column: 2; font-size: var(--nx-fs-xs); color: var(--nx-muted); font-variant-numeric: tabular-nums; }
.nx .nx-cd-muted { display: flex; align-items: center; gap: var(--nx-space-6); flex-wrap: wrap; font-size: var(--nx-fs-xs); color: var(--nx-muted); line-height: 1.5; }
.nx .nx-cd-hint { margin-top: auto; font-size: var(--nx-fs-xs); color: var(--nx-muted); }
.nx .nx-cd-ok { display: inline-flex; align-items: center; gap: var(--nx-space-4); font-size: var(--nx-fs-xs); color: var(--nx-state-ok); }

.nx .nx-cd-input { width: 100%; min-width: 0; padding: var(--nx-space-6) var(--nx-space-10); border-radius: var(--nx-r-sm); background: var(--nx-raised-2); color: var(--nx-text); box-shadow: inset 0 0 0 var(--nx-stroke) var(--nx-line-strong); font-size: var(--nx-fs); line-height: 1.45; resize: vertical; }
.nx .nx-cd-input:focus-visible { box-shadow: inset 0 0 0 var(--nx-stroke-icon) var(--nx-accent-hi); }
.nx .nx-cd-input.is-mono { font-family: var(--nx-mono); font-size: var(--nx-fs-sm); }
.nx .nx-cd-new { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; gap: var(--nx-space-12); padding: var(--nx-space-16) var(--nx-space-18) var(--nx-space-24); max-width: 820px; }
.nx .nx-cd-new h2 { font-size: var(--nx-fs-xl); font-weight: 600; color: var(--nx-text); }
.nx .nx-cd-lead { font-size: var(--nx-fs-sm); color: var(--nx-text-2); line-height: 1.5; }
.nx .nx-cd-field { display: grid; gap: var(--nx-space-5); font-size: var(--nx-fs-sm); color: var(--nx-muted); }
.nx .nx-cd-field.is-narrow { max-width: 200px; }
.nx .nx-cd-problems { margin: 0; padding-left: var(--nx-space-18); color: var(--nx-state-caution); font-size: var(--nx-fs-sm); }
.nx .nx-cd-new-foot { display: flex; align-items: center; gap: var(--nx-space-8); }

.nx .nx-cd-routes { display: grid; gap: var(--nx-space-10); padding: var(--nx-space-12); border-radius: var(--nx-r-lg); background: var(--nx-raised); box-shadow: var(--nx-card-shadow); }
.nx .nx-cd-routes > header { display: grid; gap: var(--nx-space-2); }
.nx .nx-cd-routes h3 { font-size: var(--nx-fs-md); font-weight: 600; color: var(--nx-text); }
.nx .nx-cd-routes > header p { font-size: var(--nx-fs-xs); color: var(--nx-muted); }
.nx .nx-cd-route { display: grid; grid-template-columns: minmax(0, 190px) minmax(0, 1fr); gap: var(--nx-space-4) var(--nx-space-12); align-items: center; padding-top: var(--nx-space-8); box-shadow: inset 0 var(--nx-stroke) 0 var(--nx-line); }
.nx .nx-cd-route-name { display: grid; gap: var(--nx-space-1); min-width: 0; }
.nx .nx-cd-route-name strong { font-weight: 500; color: var(--nx-text); }
.nx .nx-cd-route-name span { font-size: var(--nx-fs-xs); color: var(--nx-muted); line-height: 1.4; }
.nx .nx-cd-route-pick { display: flex; flex-wrap: wrap; align-items: center; gap: var(--nx-space-6); min-width: 0; }
.nx .nx-cd-route-pick .nx-cd-input { width: auto; flex: 1 1 150px; }
.nx .nx-cd-route-pick .nx-cd-input.is-short { flex: 1 1 120px; }
.nx .nx-cd-route .nx-cd-error { grid-column: 1 / -1; }
.nx .nx-cd-routes-pop { padding: var(--nx-space-12) var(--nx-space-18) 0; }

@container (max-width: 760px) {
  .nx .nx-cd-view { overflow: auto; }
  .nx .nx-cd-body { flex: none; flex-direction: column; }
  .nx .nx-cd-tree { flex: none; }
  .nx .nx-cd-detail { flex-basis: auto; }
  .nx .nx-cd-route { grid-template-columns: minmax(0, 1fr); }
}
.nx.is-phone .nx-cd { flex-direction: column; }
.nx.is-phone .nx-cd-list { flex-basis: auto; max-height: 34vh; box-shadow: inset 0 calc(-1 * var(--nx-stroke)) 0 var(--nx-line); }
.nx.is-phone .nx-cd-view, .nx.is-phone .nx-cd-new { padding-left: var(--nx-space-16); padding-right: var(--nx-space-16); }
.nx.is-phone .nx-cd-body { flex-direction: column; overflow: auto; }
.nx.is-phone .nx-cd-tree { flex-direction: column; align-items: stretch; overflow: visible; }
.nx.is-phone .nx-cd-level { flex-basis: auto; }
.nx.is-phone .nx-cd-detail { flex-basis: auto; }
.nx.is-phone .nx-cd-input { font-size: var(--nx-fs-lg); }
@media (max-width: 640px) { .nx .nx-cd-route { grid-template-columns: minmax(0, 1fr); } }

/* Neyvia control UI tokens, scoped to the new shell (.nx): type, radii,
   motion, state names and sizes. Colours live in nxThemes.css (Forest,
   Morning, Sunset); the logo is generated by scripts/brand/neyvia_sun_mark.py. */

:root,
.nx {
  --nx-font: "Geist", "Segoe UI Variable Text", "Segoe UI", system-ui, sans-serif;
  --nx-mono: "Geist Mono", "Cascadia Code", ui-monospace, monospace;
  --nx-display: "Newsreader", "Iowan Old Style", "Palatino Linotype", Georgia, serif;

  --nx-r-xs: 5px;
  --nx-r-sm: 7px;
  --nx-r: 10px;
  --nx-r-lg: 14px;
  --nx-r-pill: 999px;
  --nx-r-xxs: 2px;
  --nx-r-xl: 20px;
  --nx-r-2xl: 28px;

  /* Spacing: fine control rhythm through 12px, then the shared layout scale.
     Geometry (canvas coordinates, device frames) is not spacing. */
  --nx-space-1: 1px;
  --nx-space-2: 2px;
  --nx-space-3: 3px;
  --nx-space-4: 4px;
  --nx-space-5: 5px;
  --nx-space-6: 6px;
  --nx-space-7: 7px;
  --nx-space-8: 8px;
  --nx-space-9: 9px;
  --nx-space-10: 10px;
  --nx-space-11: 11px;
  --nx-space-12: 12px;
  --nx-space-14: 14px;
  --nx-space-16: 16px;
  --nx-space-18: 18px;
  --nx-space-20: 20px;
  --nx-space-24: 24px;
  --nx-space-28: 28px;
  --nx-space-32: 32px;
  --nx-space-40: 40px;
  --nx-space-48: 48px;
  --nx-space-64: 64px;
  --nx-space-80: 80px;
  --nx-space-96: 96px;

  /* Text size (Settings > Look: Small / Medium / Large) scales every step;
     nxLook.css sets --nx-ts from data-nx-text on the root. */
  --nx-ts: 1;
  --nx-fs-xs: calc(11px * var(--nx-ts));
  --nx-fs-sm: calc(12px * var(--nx-ts));
  --nx-fs: calc(13px * var(--nx-ts));
  --nx-fs-md: calc(14px * var(--nx-ts));
  --nx-fs-prose: calc(14.5px * var(--nx-ts));
  --nx-fs-lg: calc(16px * var(--nx-ts));
  --nx-fs-xl: calc(20px * var(--nx-ts));
  --nx-fs-mono: calc(12px * var(--nx-ts));
  --nx-fs-2xs: calc(10px * var(--nx-ts));
  --nx-fs-title: calc(24px * var(--nx-ts));
  --nx-fs-hero: calc(32px * var(--nx-ts));
  --nx-fs-display: calc(40px * var(--nx-ts));
  --nx-fs-display-lg: calc(48px * var(--nx-ts));
  --nx-fs-display-xl: calc(64px * var(--nx-ts));
  /* Titles in the display face (Settings > Look sets these per typeface pair). */
  --nx-display-weight: 500;
  --nx-display-tracking: -0.01em;

  /* Every one-shot transition lands between 180 and 320 ms (15 · T2): the
     scale has no step outside that band, so a new rule can't drift out of it.
     Loops (spinners, the running glow) are not transitions and only run while
     something is running; idle is still. */
  --nx-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --nx-fast: 180ms;
  --nx-med: 200ms;
  --nx-none: 0ms;
  --nx-reduced: 1ms;
  --nx-delay: 120ms;
  --nx-stagger: 45ms;
  --nx-feedback-delay: 80ms;
  --nx-spin: 800ms;
  --nx-pulse: 1800ms;
  --nx-breathe: 2400ms;
  --nx-ambient-cycle: 48s;
  --nx-ease-loop: ease-in-out;
  --nx-progress-duration: 2000ms;
  --nx-undo-window: 5000ms;
  --nx-tree-sun: #f4b847;
  --nx-tree-leaf: #5ec189;
  --nx-stroke: 1px;
  --nx-stroke-strong: 2px;
  --nx-stroke-icon: 1.5px;
  --nx-ring: 3px;
  --nx-halo: 4px;
  --nx-halo-wide: 6px;
  --nx-halo-pulse: 8px;
  --nx-halo-max: 9px;

  /* Document paper and physical preview hardware stay invariant across themes. */
  --nx-paper: #fff;
  --nx-paper-caret: CanvasText;
  --nx-paper-error: #b3261e;
  --nx-paper-sheen: rgba(255, 255, 255, 0.7);
  --nx-paper-shadow: 1px 2px 2px rgba(0, 0, 0, 0.3), 5px 12px 32px -12px rgba(0, 0, 0, 0.55);
  --nx-paper-shadow-light: 0 0 0 1px rgba(30, 28, 24, 0.06), 1px 2px 3px rgba(30, 28, 24, 0.12), 6px 14px 32px -14px rgba(30, 28, 24, 0.3);
  --nx-mark-user: rgba(255, 196, 0, 0.36);
  --nx-mark-user-line: rgba(255, 196, 0, 0.8);
  --nx-mark-model: rgba(80, 150, 255, 0.3);
  --nx-mark-model-line: rgba(80, 150, 255, 0.9);
  --nx-mark-search: rgba(255, 140, 0, 0.28);
  --nx-mark-search-active: rgba(255, 110, 0, 0.5);
  --nx-mark-search-line: rgba(255, 110, 0, 0.8);
  --nx-paper-selection: rgba(0, 90, 255, 0.28);
  --nx-device-black: #000;
  --nx-device-text: #d8d8d0;
  --nx-device-screen: #0e1115;
  --nx-device-metal: linear-gradient(160deg, #3a3c3f 0%, #1b1c1e 38%, #0e0f10 100%);
  --nx-device-metal-android: linear-gradient(160deg, #4a4d50 0%, #232527 40%, #121314 100%);
  --nx-device-shadow: inset 0 0 0 1.5px #55585c, inset 0 0 0 5px #0b0b0c, 0 0 0 1px rgba(0, 0, 0, 0.6), 18px 40px 80px -30px rgba(0, 0, 0, 0.75), 5px 12px 24px -12px rgba(0, 0, 0, 0.5);
  --nx-device-camera: radial-gradient(circle at 40% 38%, #1d2733 0 3px, #000 4px);
  --nx-device-key: #101112;
  --nx-device-key-shadow: inset 0 0 0 2px #45484c, inset 0 2px 6px rgba(0, 0, 0, 0.6);
  --nx-device-earpiece: #050505;
  --nx-device-earpiece-shadow: inset 0 0 0 1px #2c2e30;
  --nx-device-indicator: rgba(255, 255, 255, 0.85);
  --nx-device-indicator-light: rgba(0, 0, 0, 0.8);
  --nx-preview-target-offset: 110px;
  --nx-device-radius: 44px;
  --nx-device-radius-landscape: 38px;
  --nx-device-screen-radius: 30px;
  --nx-ink-on-warm: #1d1405;
  /* Fixed design samples represent the preview's own palette, not shell chrome. */
  --nx-sample-midnight: #0e1115;
  --nx-sample-midnight-accent: #72e2b5;
  --nx-sample-paper: #f1eee6;
  --nx-sample-paper-accent: #2f7c67;
  --nx-sample-warm: #17120f;
  --nx-sample-warm-accent: #e48d5d;

  /* Springs (07 §2 motion): physical curves as CSS linear(), no library.
     snappy = UI feedback, settle = panels and the docked chat, drift = ambient. */
  --nx-spring-snappy: linear(0, 0.058, 0.179, 0.322, 0.446, 0.575, 0.685, 0.774, 0.843, 0.895, 0.933, 0.957, 0.976, 0.988, 0.996, 1.001, 1.003, 1.004, 1.004, 1.003, 1.002, 1.001, 1);
  --nx-spring-settle: linear(0, 0.047, 0.154, 0.287, 0.427, 0.571, 0.686, 0.782, 0.859, 0.917, 0.96, 0.989, 1.008, 1.019, 1.025, 1.026, 1.024, 1.021, 1.018, 1.014, 1.011, 1.008, 1.005, 1.004, 1.002, 1.001, 1);
  --nx-spring-drift: linear(0, 0.04, 0.125, 0.237, 0.35, 0.464, 0.568, 0.654, 0.731, 0.791, 0.843, 0.884, 0.914, 0.939, 0.958, 0.971, 0.981, 0.988, 0.993, 0.996, 0.998, 1);
  --nx-snappy: 220ms;
  --nx-settle: 320ms;
  /* drift = slow fills (progress bars, meters): the slowest a transition may be. */
  --nx-drift: 320ms;

  /* Leaf light, one meaning each (07 §2-3): the sun = something is running
     (amber) or needs you (sunset orange); green is the calm surface and its
     actions. A warning that asks nothing of you is caution: no sun, the
     warning shape carries it. Components use these names, never raw colours. */
  --nx-state-running: var(--nx-amber);
  /* Running as text (labels, counts, timers): the same amber where it reads at
     4.5:1; Morning deepens it to ochre and keeps the bright amber for dots and fills. */
  --nx-state-running-text: var(--nx-state-running);
  --nx-state-needs: var(--nx-gold);
  --nx-state-ok: color-mix(in srgb, var(--nx-green) 70%, transparent);
  --nx-state-error: var(--nx-red);
  --nx-state-caution: var(--nx-text-2);
  --nx-caution-soft: color-mix(in srgb, var(--nx-text) 6%, transparent);
  --nx-caution-line: color-mix(in srgb, var(--nx-text) 22%, transparent);

  /* One sun, top-left (07 §2 "depth, not borders"): every cast shadow falls
     right and down at the same angle (x = 0.45 y). --nx-shade is per theme. */
  --nx-lift-1: 1px 2px 4px -1px var(--nx-shade);
  --nx-lift-2: 5px 11px 30px -18px var(--nx-shade);
  --nx-lift-3: 11px 24px 60px -22px var(--nx-shade);
  /* A panel's edge where it overlaps another: contact shade with no direction. */
  --nx-edge: 0 0 40px -18px var(--nx-shade);

  /* Density (Calm / Workshop / Grove): one data model, three spacings. */
  --nx-row-pad: 7px;
  --nx-row-gap: 2px;
  --nx-strip-h: 28px;
  --nx-dock-w: 380px;

  --nx-sidebar-w: 276px;
  --nx-panel-w: 400px;
  --nx-canopy-w: 292px;
  --nx-thread-w: 760px;
  --nx-safe-bottom: env(safe-area-inset-bottom, 0px);
  --nx-safe-top: env(safe-area-inset-top, 0px);

}

/* Re-derive colours on each app window: inherited custom properties otherwise
   resolve against the shell's palette rather than that window's skin. */
:root, .nx, .nx [data-nx-skin] {
  --nx-accent-hover: color-mix(in srgb, var(--nx-accent) 92%, var(--nx-text));
  --nx-accent-press: color-mix(in srgb, var(--nx-accent) 86%, var(--nx-text));
  --nx-on-error: var(--nx-on-accent);
  --nx-on-success: var(--nx-on-accent);
}

.nx[data-nx-density="calm"] {
  --nx-row-pad: 9px;
  --nx-row-gap: 4px;
  --nx-sidebar-w: 288px;
}

.nx[data-nx-density="grove"] {
  --nx-row-pad: 5px;
  --nx-row-gap: 1px;
  --nx-sidebar-w: 260px;
  --nx-dock-w: 360px;
}

/* Local reset: the legacy stylesheet styles bare elements globally. */
.nx,
.nx * {
  box-sizing: border-box;
}

.nx {
  position: fixed;
  inset: 0;
  display: flex;
  background: var(--nx-bg);
  color: var(--nx-text);
  font: 400 var(--nx-fs) / 1.45 var(--nx-font);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overflow: hidden;
}

.nx button, .nx input, .nx textarea, .nx select {
  font: inherit;
  color: inherit;
  letter-spacing: inherit;
  margin: 0;
}

.nx input, .nx textarea, .nx select {
  width: auto;
  min-height: 0;
  border: 0;
  border-radius: 0;
  background: none;
  padding: 0;
  box-shadow: none;
}

.nx button {
  background: none;
  border: 0;
  padding: 0;
  cursor: pointer;
  text-align: inherit;
}

.nx button:disabled {
  cursor: default;
}

.nx :where(h1, h2, h3, h4, p, ul, ol, figure) {
  margin: 0;
  font-family: inherit;
}

.nx a {
  color: var(--nx-accent-text);
  text-decoration: none;
}

.nx a:hover {
  text-decoration: underline;
}

/* Keyboard focus is always visible. An outline, not a box-shadow, so a component's own
   shadow (outline buttons, cards) can never hide it. Rows and items in scrolling lists draw
   it inside so the list's edge doesn't clip it. Programmatic focus targets (tabindex -1:
   dialogs, the tour) and full-pane editors don't get a frame; text fields keep their own
   inset ring. */
.nx.nx :focus-visible {
  outline: 2px solid var(--nx-focus-ring);
  outline-offset: 2px;
}
.nx.nx :is(.nx-row, .nx-row-more, .nx-menu-item, .nx-picker-row, .nx-folder-row-main, .nx-tile, .nx-option, .nx-splitter,
  .nx-side-section-head, .nx-files-list, .nx-pdf-scroll, .nx-diff, .nx-pre, [role=option], [role=menuitem], [role=tab]):focus-visible {
  outline-offset: -2px;
}
.nx.nx :is([tabindex="-1"], .nx-notes-text, .nx-fp-text, .nx-input, .nx-aware-input, .nx-composer textarea, .nx-search input,
  .nx-folder-input input, .nx-voice-type input, .nx-docs-search input, .nx-pdf-search input):focus-visible {
  outline: none;
}

.nx ::selection {
  background: var(--nx-selection);
}

.nx :where(.nx-scroll) {
  overflow: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--nx-scrollbar) transparent;
}

@media (prefers-reduced-motion: reduce) {
  .nx *,
  .nx *::before,
  .nx *::after {
    animation-duration: var(--nx-reduced) !important;
    animation-iteration-count: 1 !important;
    transition-duration: var(--nx-reduced) !important;
  }
}

/* Placement (NxPlacement): every app or pane is one window, drawn in one
   layer over its slot. Colours and radii come from the theme tokens only. */

.nx .nx-surfaces { display: contents; }
.nx .nx-slot { flex: 1 1 auto; min-width: 0; min-height: 0; }
.nx .nx-region > .nx-slot-side { width: var(--nx-panel-w); }
.nx .nx-panel-overlay:has(> .nx-slot) { pointer-events: none; }
.nx .nx-panel-overlay > .nx-slot-side { width: var(--nx-panel-w); }

.nx .nx-surface {
  position: fixed; z-index: 5; display: flex; flex-direction: column; min-width: 0; min-height: 0; overflow: hidden;
  background: var(--nx-panel);
}
.nx .nx-surface > .nx-stage { flex: 1 1 auto; min-height: 0; }
.nx .nx-surface.is-moving { transition: left var(--nx-settle) var(--nx-spring-settle), top var(--nx-settle) var(--nx-spring-settle), width var(--nx-settle) var(--nx-spring-settle), height var(--nx-settle) var(--nx-spring-settle), border-radius var(--nx-fast) var(--nx-ease); }
.nx .nx-surface.is-hidden { visibility: hidden; pointer-events: none; }
/* Opening fades a window in, closing fades it out: one app replacing another crossfades. */
.nx .nx-surface.is-entering { animation: nx-surface-in var(--nx-med) var(--nx-ease) both; }
.nx .nx-surface.is-leaving { z-index: 4; pointer-events: none; animation: nx-surface-out var(--nx-med) var(--nx-ease) both; }
@keyframes nx-surface-in { from { opacity: 0; } to { opacity: 1; } }
@keyframes nx-surface-out { from { opacity: 1; } to { opacity: 0; transform: scale(0.985); } }
/* Into the bubble and back out of it: the window keeps its size and shrinks toward the bubble's
   point (or grows from it), on the settle spring, so nothing jumps. */
.nx .nx-surface.is-folding {
  z-index: 64; transform-origin: 0 0; pointer-events: none; transform: translate(var(--nx-fold-x), var(--nx-fold-y)) scale(var(--nx-fold-s)); opacity: 0;
  border-radius: var(--nx-r-xl); box-shadow: var(--nx-shadow-pop);
  transition: transform var(--nx-settle) var(--nx-spring-settle), opacity var(--nx-med) var(--nx-ease) var(--nx-fast), border-radius var(--nx-fast) var(--nx-ease);
}
.nx .nx-surface.is-unfolding.is-unfolding { transform-origin: 0 0; animation: nx-unfold var(--nx-settle) var(--nx-spring-settle) both; }
@keyframes nx-unfold {
  from { transform: translate(var(--nx-fold-x), var(--nx-fold-y)) scale(var(--nx-fold-s)); opacity: 0; border-radius: var(--nx-r-xl); }
  40% { opacity: 1; }
  to { transform: none; opacity: 1; }
}
.nx .nx-surface.is-side.is-right { box-shadow: calc(-1 * var(--nx-stroke)) 0 0 var(--nx-line); }
.nx .nx-surface.is-side.is-left { box-shadow: var(--nx-stroke) 0 0 var(--nx-line); }
.nx .nx-surface.is-side.is-floating { z-index: 21; box-shadow: var(--nx-edge); }
.nx .nx-surface.is-full { z-index: 50; background: var(--nx-bg); }
/* Under a full-screen window the shell is out of sight, for the eye and for the keyboard and screen
   readers (visibility removes it from both); toasts, banners and bubbles stay above it. */
.nx.has-full .nx-os > .nx-region, .nx.has-full .nx-os > .nx-main, .nx.has-full .nx-os > .nx-panel-overlay,
.nx.has-full .nx-os > .nx-slot, .nx.has-full .nx-strip,
.nx.has-full .nx-surface.is-main, .nx.has-full .nx-surface.is-side { visibility: hidden; }
.nx .nx-surface.is-bubble { z-index: 65; background: var(--nx-bg); border-radius: var(--nx-r-lg); box-shadow: var(--nx-shadow-pop), 0 0 0 var(--nx-stroke) var(--nx-line); }
.nx .nx-surface.is-bubble:not(.is-hidden) { animation: nx-peek-in var(--nx-settle) var(--nx-spring-settle) both; }
.nx .nx-surface.is-dragged { z-index: 71; }
@keyframes nx-peek-in { from { opacity: 0; transform: scale(0.96); } to { opacity: 1; transform: none; } }

/* The title bar is the handle; side and bubble windows get a tighter bar. */
.nx .nx-stage-head.is-handle { cursor: grab; touch-action: none; user-select: none; }
.nx .nx-surface.is-dragged .nx-stage-head { cursor: grabbing; }
.nx .nx-surface.is-side .nx-stage-head,
.nx .nx-surface.is-bubble .nx-stage-head { height: 42px; padding-left: var(--nx-space-12); gap: var(--nx-space-4); }
.nx .nx-surface.is-side .nx-stage-title,
.nx .nx-surface.is-bubble .nx-stage-title { flex: 1 1 auto; overflow: hidden; }
.nx .nx-surface.is-side .nx-stage-head > .nx-head-spacer,
.nx .nx-surface.is-bubble .nx-stage-head > .nx-head-spacer { display: none; }

.nx .nx-place { display: inline-flex; align-items: center; gap: var(--nx-space-2); padding: var(--nx-space-2); border-radius: var(--nx-r-sm); box-shadow: inset 0 0 0 var(--nx-stroke) var(--nx-line); flex: none; }
.nx .nx-place .nx-iconbtn.is-active { background: var(--nx-accent-soft); color: var(--nx-accent-text); }

/* Drop zones while a window is dragged by its title bar. */
.nx .nx-dropzones { position: fixed; inset: 0; z-index: 72; pointer-events: none; }
.nx .nx-dropzone {
  position: absolute; display: grid; place-items: center; border-radius: var(--nx-r-lg);
  background: color-mix(in srgb, var(--nx-accent-hi) 10%, var(--nx-bg) 55%); box-shadow: inset 0 0 0 var(--nx-stroke-icon) color-mix(in srgb, var(--nx-accent-hi) 40%, transparent);
  color: var(--nx-text-2); font-size: var(--nx-fs-sm); font-weight: 600;
  transition: background var(--nx-fast) var(--nx-ease), box-shadow var(--nx-fast) var(--nx-ease);
}
.nx .nx-dropzone > span { padding: var(--nx-space-6) var(--nx-space-12); border-radius: var(--nx-r-pill); background: var(--nx-raised); box-shadow: var(--nx-shadow-pop); }
.nx .nx-dropzone.is-over { background: color-mix(in srgb, var(--nx-accent-hi) 26%, var(--nx-bg) 60%); box-shadow: inset 0 0 0 var(--nx-stroke-strong) var(--nx-accent-hi); color: var(--nx-text); }
.nx .nx-dropzone.is-side-left { left: 8px; top: 8px; bottom: 8px; width: calc(20% - 16px); }
.nx .nx-dropzone.is-side-right { right: 8px; top: 8px; bottom: 8px; width: calc(20% - 16px); }
.nx .nx-dropzone.is-full { left: 20%; right: 20%; top: 8px; height: calc(16% - 16px); }
.nx .nx-dropzone.is-main { left: 20%; right: 20%; top: 16%; bottom: 16%; margin: var(--nx-space-8); }
.nx .nx-dropzone.is-bubble { left: 20%; right: 20%; bottom: 8px; height: calc(16% - 16px); }
.nx .nx-drop-ghost {
  position: absolute; top: 0; left: 0; padding: var(--nx-space-6) var(--nx-space-10); border-radius: var(--nx-r-sm); background: var(--nx-raised); box-shadow: var(--nx-shadow-pop);
  font-size: var(--nx-fs-sm); font-weight: 600; white-space: nowrap;
}

/* Apps in bubbles: same feel as the floating chats (nxBubbles.css), a square-ish app mark. */
.nx .nx-wbubbles { position: fixed; inset: 0; z-index: 66; pointer-events: none; }
.nx .nx-wbubble-wrap { position: absolute; top: 0; left: 0; transition: transform var(--nx-settle) var(--nx-spring-settle); }
.nx .nx-wbubble {
  position: relative; width: 52px; height: 52px; border-radius: var(--nx-r-xl); pointer-events: auto; display: grid; place-items: center;
  background: var(--nx-raised); color: var(--nx-accent-text); box-shadow: var(--nx-shadow-pop), inset 0 0 0 var(--nx-stroke-icon) var(--nx-line-strong);
  cursor: grab; touch-action: none; transition: box-shadow var(--nx-fast) var(--nx-ease), scale var(--nx-fast) var(--nx-ease);
}
.nx .nx-wbubble:hover { scale: 1.04; }
.nx .nx-wbubble.is-dragging { cursor: grabbing; }
.nx .nx-wbubble-wrap:has(.is-dragging) { transition: none; }
.nx .nx-wbubble.is-open { box-shadow: var(--nx-shadow-pop), 0 0 0 var(--nx-stroke-strong) var(--nx-accent-hi); }
.nx .nx-wbubble:focus-visible { outline: 2px solid var(--nx-accent-hi); outline-offset: 3px; }
.nx .nx-wbubble-name {
  position: absolute; top: 50%; right: calc(100% + 8px); translate: 0 -50%; padding: var(--nx-space-3) var(--nx-space-8); border-radius: var(--nx-r-xs); white-space: nowrap;
  background: var(--nx-raised); box-shadow: var(--nx-shadow-pop); font-size: var(--nx-fs-xs); font-weight: 600; color: var(--nx-text-2);
  opacity: 0; transition: opacity var(--nx-fast) var(--nx-ease); pointer-events: none;
}
.nx .nx-wbubble-name.is-left { right: auto; left: calc(100% + 8px); }
.nx .nx-wbubble-wrap:hover .nx-wbubble-name,
.nx .nx-wbubble:focus-visible + .nx-wbubble-name { opacity: 1; }

/* Phone: a side window splits the screen with the chat, under it. */
.nx.is-phone .nx-os.has-split { flex-direction: column; }
.nx.is-phone .nx-os.has-split > .nx-slot-side { flex: 0 0 46%; border-top: 1px solid var(--nx-line); }
.nx.is-phone .nx-os.has-split > :not(.nx-slot-side) { flex: 1 1 0; min-height: 0; }
.nx.is-phone .nx-surface.is-side { box-shadow: 0 calc(-1 * var(--nx-stroke)) 0 var(--nx-line); }
.nx.is-phone .nx-surface .nx-place { gap: 0; }
.nx.is-phone .nx-surface .nx-stage-title span { display: none; }

/* LAYA as a window (NxLaya NxLayaApp), and its popover's "open as a window". */
.nx .nx-laya-app { flex: 1 1 auto; min-height: 0; padding: var(--nx-space-18) var(--nx-space-20); }
.nx .nx-laya-app > .nx-laya-detail { display: grid; gap: var(--nx-space-8); max-width: 720px; }
.nx .nx-laya-window { display: flex; justify-content: flex-end; padding: var(--nx-space-4) var(--nx-space-8) var(--nx-space-8); border-top: 1px solid var(--nx-line); }

@media (prefers-reduced-motion: reduce) {
  .nx .nx-surface.is-moving, .nx .nx-wbubble-wrap, .nx .nx-surface.is-folding { transition: none; }
  .nx .nx-surface.is-bubble:not(.is-hidden), .nx .nx-surface.is-unfolding.is-unfolding, .nx .nx-surface.is-entering, .nx .nx-surface.is-leaving { animation: none; }
  .nx .nx-surface.is-folding { opacity: 0; transform: none; }
}
.nx[data-nx-motion="reduce"] .nx-surface.is-moving,
.nx[data-nx-motion="reduce"] .nx-wbubble-wrap,
.nx[data-nx-motion="reduce"] .nx-surface.is-folding { transition: none; }
.nx[data-nx-motion="reduce"] .nx-surface.is-folding { opacity: 0; transform: none; }
.nx[data-nx-motion="reduce"] .nx-surface.is-bubble:not(.is-hidden),
.nx[data-nx-motion="reduce"] .nx-surface.is-unfolding.is-unfolding,
.nx[data-nx-motion="reduce"] .nx-surface.is-entering,
.nx[data-nx-motion="reduce"] .nx-surface.is-leaving { animation: none; }

/* The four themes of the control UI. Each is only colour; spacing, type and
   motion live in nxTokens.css. Components use the names, never raw colours.

   Forest  (dark)    late evening under the trees: near-black greens, cream text,
                     leaf-green actions, the sun only where something happens.
   Morning (light)   first sun through the canopy on warm paper: moss-shaded
                     sidebar, lit cards that cast forest shade, deep leaf greens.
   Sunset  (sunset)  twilight: a cool violet sky over a warm horizon,
                     sunset-orange actions, gold for what needs you.
   Night Green (night) dark water: deep blue-green, sea-green actions,
                     light from the surface above, glowing specks below.

   In every theme the sun means something is happening: --nx-amber = running,
   --nx-gold = needs you. Nothing else is painted with them (15 · T2): actions
   are the theme's accent, warnings that ask nothing are caution (nxTokens).

   Light: one low sun, top-left. --nx-ambient is the still leaf light any
   surface may use; --nx-ambient-sun and --nx-dapple are the sunlight the
   shell's ambient layer adds only while something runs (nxMotion.css).
   --nx-shade is the colour every cast shadow (--nx-lift-*) uses.

   Every text colour (--nx-muted, --nx-faint, and gold/red/green where they are
   text) reads at 4.5:1 or better on every surface of its theme, hover rows
   included (WCAG AA; checked by web/a11y/nx-a11y-audit.mjs). */

:root,
.nx,
.nx[data-nx-theme="dark"] {
  /* Forest (reworked in the Look track): a deep green night, not grey-black.
     Surfaces step up in green-tinted layers (sidebar < page < panel < card <
     selected), lines are cool leaf-white instead of cream so edges read
     crisp, and the leaf accent is brighter and more saturated so actions
     stand out. Text is a clean green-white; every text colour keeps 4.5:1 on
     every surface and hover state (checked by nxLookModel.test.js). */
  --nx-bg: #0d1612;
  --nx-sidebar: #0a120e;
  --nx-panel: #111c17;
  --nx-raised: #15221b;
  --nx-raised-2: #1b2b23;
  --nx-hover: rgba(214, 240, 222, 0.05);
  --nx-active: rgba(214, 240, 222, 0.09);
  --nx-line: rgba(214, 240, 222, 0.08);
  --nx-line-strong: rgba(214, 240, 222, 0.15);

  --nx-text: #edf2ea;
  --nx-text-2: #cbd7cd;
  --nx-muted: #a5b6a9;
  --nx-faint: #96a99b;

  --nx-accent: #46b077;
  --nx-on-accent: #03140b; /* text on an --nx-accent fill, 4.5:1 or better */
  --nx-accent-hi: #63c98f;
  --nx-accent-text: #95dfb3;
  --nx-accent-soft: rgba(99, 201, 143, 0.14);
  --nx-amber: #f4b847;
  --nx-gold: #f39a3d;
  --nx-gold-soft: rgba(243, 154, 61, 0.14);
  --nx-green: #74d29c;
  --nx-green-soft: rgba(116, 210, 156, 0.12);
  --nx-red: #f48a7a;
  --nx-red-soft: rgba(244, 138, 122, 0.12);
  --nx-sun: linear-gradient(180deg, #ffc455 0%, #f58a2e 55%, #e3582a 100%);
  --nx-sun-ink: #2a1406;

  --nx-focus: 0 0 0 var(--nx-stroke-strong) var(--nx-bg), 0 0 0 var(--nx-halo) var(--nx-focus-ring);
  --nx-focus-ring: #63c98f;
  --nx-shade: rgba(0, 6, 3, 0.62);
  --nx-shadow-pop: 0 0 0 1px var(--nx-line-strong), inset 0 1px 0 rgba(214, 240, 222, 0.05), 8px 18px 48px -12px rgba(0, 6, 3, 0.75), 1px 2px 6px rgba(0, 6, 3, 0.4);
  --nx-card-shadow: 0 0 0 1px var(--nx-line), inset 0 1px 0 rgba(214, 240, 222, 0.04), 6px 14px 30px -20px rgba(0, 6, 3, 0.8);
  --nx-selection: rgba(99, 201, 143, 0.3);
  --nx-scrollbar: rgba(214, 240, 222, 0.16);
  --nx-state-stale: #8a7560;
  --nx-scrim: rgba(2, 8, 5, 0.6);
  /* Leaf light: a soft green glow through the canopy top-right and moss light
     pooled bottom-left; the low sun top-left only while something runs. */
  --nx-ambient:
    radial-gradient(1200px 560px at 78% -16%, rgba(78, 186, 128, 0.16), transparent 64%),
    radial-gradient(900px 520px at -4% 108%, rgba(46, 130, 88, 0.12), transparent 62%),
    radial-gradient(700px 360px at 4% -10%, rgba(244, 184, 71, 0.035), transparent 70%);
  --nx-ambient-sun: radial-gradient(900px 460px at 8% -14%, rgba(244, 184, 71, 0.075), transparent 64%);
  /* Round patches of sun on the forest floor (07 §2 komorebi): each leaf gap is a pinhole. */
  --nx-dapple:
    radial-gradient(70px 46px at 20% 16%, rgba(244, 196, 102, 0.075), transparent 70%),
    radial-gradient(44px 30px at 29% 24%, rgba(244, 196, 102, 0.065), transparent 70%),
    radial-gradient(110px 70px at 10% 30%, rgba(244, 184, 71, 0.05), transparent 70%),
    radial-gradient(56px 38px at 38% 11%, rgba(244, 196, 102, 0.05), transparent 70%),
    radial-gradient(36px 24px at 16% 40%, rgba(244, 196, 102, 0.06), transparent 70%);
  color-scheme: dark;
}

/* Forest depth: the sidebar is the shaded forest edge with a little canopy light
   at the top; cards are a step lighter with a faint lit top edge. */
.nx[data-nx-theme="dark"] .nx-side { background: linear-gradient(180deg, color-mix(in srgb, var(--nx-sidebar) 92%, var(--nx-text)) 0%, var(--nx-sidebar) 45%, color-mix(in srgb, var(--nx-sidebar) 85%, var(--nx-bg)) 100%); }
.nx[data-nx-theme="dark"] .nx-widget { background: linear-gradient(180deg, color-mix(in srgb, var(--nx-raised) 97%, var(--nx-text)) 0%, var(--nx-raised) 100%); box-shadow: var(--nx-card-shadow); }
.nx[data-nx-theme="dark"] .nx-composer { background: var(--nx-raised); }
/* Let the canopy light through: the chat column was an opaque sheet over the ambient layer. */
.nx[data-nx-theme="dark"] .nx-work-chat { background: transparent; }

.nx[data-nx-theme="light"] {
  /* Morning: first sun through the canopy onto warm paper (plan 19 R3). The low
     sun sits top-left, so whatever is closer to you is brighter, catches light on
     its top edge and casts a soft shadow down and right. Shade is the forest's:
     green-grey, never brown. Back to front: the sidebar is the forest edge (moss
     paper), the page is paper, panels and cards are lit paper, a selected or
     lifted control is the brightest thing. Warmth stays rare: amber/gold for
     running and needs-you, the sun bloom only while something runs. */
  --nx-bg: #f5f1e6;
  --nx-sidebar: #ebe9da;
  --nx-panel: #faf7f0;
  --nx-raised: #fffdf9;
  --nx-raised-2: #ffffff;
  --nx-hover: rgba(42, 58, 34, 0.055);
  --nx-active: rgba(42, 58, 34, 0.09);
  --nx-line: rgba(42, 54, 32, 0.11);
  --nx-line-strong: rgba(42, 54, 32, 0.2);

  --nx-text: #17221a;
  --nx-text-2: #323f30;
  --nx-muted: #465143;
  --nx-faint: #555d4f;

  --nx-accent: #3a774b;
  --nx-on-accent: #ffffff; /* text on an --nx-accent fill, 4.5:1 or better */
  --nx-accent-hi: #4a8f5d;
  --nx-accent-text: #245a35;
  --nx-accent-soft: rgba(58, 119, 75, 0.11);
  /* The sun stays bright where it is a mark (tree sun, spinner, dots); as text
     it is the deeper ochre below, which reads at 4.5:1 on every Morning surface. */
  --nx-amber: #d4930f;
  --nx-state-running-text: #7a4f08;
  --nx-gold: #8f480b;
  --nx-gold-soft: rgba(232, 137, 43, 0.15);
  --nx-green: #226640;
  --nx-green-soft: rgba(47, 138, 85, 0.1);
  --nx-red: #a1372d;
  --nx-red-soft: rgba(196, 69, 58, 0.1);

  --nx-focus: 0 0 0 var(--nx-stroke-strong) var(--nx-bg), 0 0 0 var(--nx-halo) var(--nx-focus-ring);
  --nx-focus-ring: #2f7d4f;
  /* Forest shade: every cast shadow (--nx-lift-*) uses it. */
  --nx-shade: rgba(30, 50, 28, 0.2);
  /* Lit paper: a ring, sunlight on the top edge, a short contact shadow and a
     soft cast shadow down-right (x = 0.45 y, like --nx-lift-*). */
  --nx-card-shadow: 0 0 0 1px var(--nx-line), inset 0 1px 0 rgba(255, 255, 255, 0.9), 1px 2px 3px -1px rgba(30, 50, 28, 0.1), 7px 15px 30px -18px rgba(30, 50, 28, 0.26);
  --nx-shadow-pop: 0 0 0 1px var(--nx-line-strong), inset 0 1px 0 rgba(255, 255, 255, 0.9), 9px 20px 48px -14px rgba(26, 44, 26, 0.3), 1px 2px 6px rgba(26, 44, 26, 0.08);
  --nx-selection: rgba(58, 119, 75, 0.22);
  --nx-scrollbar: rgba(42, 54, 32, 0.22);
  --nx-state-stale: #7d6a52;
  /* Overlays dim the page like a cloud over the trees: cool green-grey, not khaki. */
  --nx-scrim: rgba(26, 40, 28, 0.22);
  /* Still: leaf light pooled bottom-right and a little canopy shade along the top. */
  --nx-ambient:
    radial-gradient(1100px 620px at 104% 110%, rgba(58, 119, 75, 0.13), transparent 62%),
    radial-gradient(1400px 260px at 60% -10%, rgba(42, 74, 40, 0.05), transparent 70%);
  /* Running: the low morning sun warms the top-left. */
  --nx-ambient-sun:
    radial-gradient(1000px 560px at -4% -14%, rgba(255, 190, 80, 0.2), transparent 60%),
    radial-gradient(520px 300px at 6% -6%, rgba(255, 214, 140, 0.16), transparent 70%);
  /* Komorebi by day: small warm sun flecks where the leaves part. (Leaf-shade
     blobs were tried and band into grey rings on paper, so the shade stays out.) */
  --nx-dapple:
    radial-gradient(34px 22px at 22% 18%, rgba(255, 200, 100, 0.24), transparent 72%),
    radial-gradient(22px 15px at 13% 27%, rgba(255, 206, 110, 0.2), transparent 72%),
    radial-gradient(28px 18px at 34% 12%, rgba(255, 214, 130, 0.18), transparent 72%),
    radial-gradient(18px 12px at 29% 30%, rgba(255, 206, 110, 0.16), transparent 72%),
    radial-gradient(40px 26px at 8% 12%, rgba(255, 210, 120, 0.16), transparent 72%);
  color-scheme: light;
}

/* Morning depth (plan 19 R3). In the dark themes a nested surface is lighter, so
   it reads as closer; on paper there is little room above white, so Morning lifts
   with light and shadow instead: the sidebar is the shaded forest edge, the page
   paper, cards lit paper with a cast shadow, and a selected row or control rises
   into the light rather than sinking into a darker stone. */
.nx[data-nx-theme="light"] .nx-side {
  background:
    radial-gradient(360px 220px at -8% -6%, color-mix(in srgb, var(--nx-accent) 22%, transparent), transparent 70%),
    linear-gradient(180deg, var(--nx-raised) 0%, var(--nx-sidebar) 40%, var(--nx-raised) 100%);
  box-shadow: inset calc(-1 * var(--nx-stroke)) 0 0 color-mix(in srgb, var(--nx-line) 55%, transparent);
}
.nx[data-nx-theme="light"] .nx-row.is-active,
.nx[data-nx-theme="light"] .nx-kid-row.is-active,
.nx[data-nx-theme="light"] .nx-rail-chat.is-active,
.nx[data-nx-theme="light"] .nx-onb-rail-step.is-on {
  background: var(--nx-raised-2);
  box-shadow: 0 0 0 var(--nx-stroke) var(--nx-line), var(--nx-lift-1);
}
.nx[data-nx-theme="light"] .nx-seg { background: color-mix(in srgb, var(--nx-text) 6%, transparent); }
.nx[data-nx-theme="light"] .nx-widget { background: var(--nx-panel); }
.nx[data-nx-theme="light"] .nx-continue-card {
  background: linear-gradient(160deg, var(--nx-raised) 30%, color-mix(in srgb, var(--nx-accent) 6%, var(--nx-raised)));
  box-shadow: var(--nx-card-shadow);
}
.nx[data-nx-theme="light"] .nx-continue-card:hover {
  box-shadow: 0 0 0 var(--nx-stroke) color-mix(in srgb, var(--nx-accent-hi) 45%, transparent), inset 0 var(--nx-stroke) 0 var(--nx-line-strong), var(--nx-lift-2);
}
.nx[data-nx-theme="light"] .nx-composer { background: var(--nx-raised-2); }
/* Cards you pick (launcher tiles, setup choices, Canopy cards) are lit paper that
   rises on hover, not a grey stone sunk into the page; their icon wells are leaf. */
.nx[data-nx-theme="light"] .nx-launcher-body { background: var(--nx-panel); }
.nx[data-nx-theme="light"] .nx-tile,
.nx[data-nx-theme="light"] .nx-onb-pick,
.nx[data-nx-theme="light"] .nx-canopy-card { background: var(--nx-raised-2); box-shadow: var(--nx-card-shadow); }
.nx[data-nx-theme="light"] .nx-tile:hover:not(:disabled),
.nx[data-nx-theme="light"] .nx-tile:focus-visible,
.nx[data-nx-theme="light"] .nx-onb-pick:hover {
  background: var(--nx-raised-2);
  box-shadow: 0 0 0 var(--nx-stroke) var(--nx-line-strong), inset 0 var(--nx-stroke) 0 var(--nx-line-strong), var(--nx-lift-2);
}
.nx[data-nx-theme="light"] .nx-tile-icon { color: var(--nx-accent-text); background: var(--nx-accent-soft); }
/* Let the ambient layer through: the chat column is otherwise an opaque sheet of
   --nx-bg over it (.nx-main already paints the same colour underneath). */
.nx[data-nx-theme="light"] .nx-work-chat { background: transparent; }

.nx[data-nx-theme="sunset"] {
  /* Twilight: a cool violet sky over a warm horizon. The surfaces are the sky
     (indigo-violet), so the sun colours stay rare and bright: orange for the
     one primary action, gold for what needs you. */
  --nx-bg: #141020;
  --nx-sidebar: #110d1b;
  --nx-panel: #181325;
  --nx-raised: #201a30;
  --nx-raised-2: #29213b;
  --nx-hover: rgba(236, 222, 255, 0.05);
  --nx-active: rgba(236, 222, 255, 0.09);
  --nx-line: rgba(236, 222, 255, 0.08);
