/* Neyvia control UI tokens, scoped to the new shell (.nx): type, radii,
   motion, state names and sizes. Colours live in nxThemes.css (Forest,
   Morning, Sunset); the logo is generated by scripts/brand/neyvia_sun_mark.py. */

:root,
.nx {
  --nx-font: "Geist", "Segoe UI Variable Text", "Segoe UI", system-ui, sans-serif;
  --nx-mono: "Geist Mono", "Cascadia Code", ui-monospace, monospace;
  --nx-display: "Newsreader", "Iowan Old Style", "Palatino Linotype", Georgia, serif;

  --nx-r-xs: 5px;
  --nx-r-sm: 7px;
  --nx-r: 10px;
  --nx-r-lg: 14px;
  --nx-r-pill: 999px;
  --nx-r-xxs: 2px;
  --nx-r-xl: 20px;
  --nx-r-2xl: 28px;

  /* Spacing: fine control rhythm through 12px, then the shared layout scale.
     Geometry (canvas coordinates, device frames) is not spacing. */
  --nx-space-1: 1px;
  --nx-space-2: 2px;
  --nx-space-3: 3px;
  --nx-space-4: 4px;
  --nx-space-5: 5px;
  --nx-space-6: 6px;
  --nx-space-7: 7px;
  --nx-space-8: 8px;
  --nx-space-9: 9px;
  --nx-space-10: 10px;
  --nx-space-11: 11px;
  --nx-space-12: 12px;
  --nx-space-14: 14px;
  --nx-space-16: 16px;
  --nx-space-18: 18px;
  --nx-space-20: 20px;
  --nx-space-24: 24px;
  --nx-space-28: 28px;
  --nx-space-32: 32px;
  --nx-space-40: 40px;
  --nx-space-48: 48px;
  --nx-space-64: 64px;
  --nx-space-80: 80px;
  --nx-space-96: 96px;

  /* Text size (Settings > Look: Small / Medium / Large) scales every step;
     nxLook.css sets --nx-ts from data-nx-text on the root. */
  --nx-ts: 1;
  --nx-fs-xs: calc(11px * var(--nx-ts));
  --nx-fs-sm: calc(12px * var(--nx-ts));
  --nx-fs: calc(13px * var(--nx-ts));
  --nx-fs-md: calc(14px * var(--nx-ts));
  --nx-fs-prose: calc(14.5px * var(--nx-ts));
  --nx-fs-lg: calc(16px * var(--nx-ts));
  --nx-fs-xl: calc(20px * var(--nx-ts));
  --nx-fs-mono: calc(12px * var(--nx-ts));
  --nx-fs-2xs: calc(10px * var(--nx-ts));
  --nx-fs-title: calc(24px * var(--nx-ts));
  --nx-fs-hero: calc(32px * var(--nx-ts));
  --nx-fs-display: calc(40px * var(--nx-ts));
  --nx-fs-display-lg: calc(48px * var(--nx-ts));
  --nx-fs-display-xl: calc(64px * var(--nx-ts));
  /* Titles in the display face (Settings > Look sets these per typeface pair). */
  --nx-display-weight: 500;
  --nx-display-tracking: -0.01em;

  /* Every one-shot transition lands between 180 and 320 ms (15 · T2): the
     scale has no step outside that band, so a new rule can't drift out of it.
     Loops (spinners, the running glow) are not transitions and only run while
     something is running; idle is still. */
  --nx-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --nx-fast: 180ms;
  --nx-med: 200ms;
  --nx-none: 0ms;
  --nx-reduced: 1ms;
  --nx-delay: 120ms;
  --nx-stagger: 45ms;
  --nx-feedback-delay: 80ms;
  --nx-spin: 800ms;
  --nx-pulse: 1800ms;
  --nx-breathe: 2400ms;
  --nx-ambient-cycle: 48s;
  --nx-ease-loop: ease-in-out;
  --nx-progress-duration: 2000ms;
  --nx-undo-window: 5000ms;
  --nx-tree-sun: #f4b847;
  --nx-tree-leaf: #5ec189;
  --nx-stroke: 1px;
  --nx-stroke-strong: 2px;
  --nx-stroke-icon: 1.5px;
  --nx-ring: 3px;
  --nx-halo: 4px;
  --nx-halo-wide: 6px;
  --nx-halo-pulse: 8px;
  --nx-halo-max: 9px;

  /* Document paper and physical preview hardware stay invariant across themes. */
  --nx-paper: #fff;
  --nx-paper-caret: CanvasText;
  --nx-paper-error: #b3261e;
  --nx-paper-sheen: rgba(255, 255, 255, 0.7);
  --nx-paper-shadow: 1px 2px 2px rgba(0, 0, 0, 0.3), 5px 12px 32px -12px rgba(0, 0, 0, 0.55);
  --nx-paper-shadow-light: 0 0 0 1px rgba(30, 28, 24, 0.06), 1px 2px 3px rgba(30, 28, 24, 0.12), 6px 14px 32px -14px rgba(30, 28, 24, 0.3);
  --nx-mark-user: rgba(255, 196, 0, 0.36);
  --nx-mark-user-line: rgba(255, 196, 0, 0.8);
  --nx-mark-model: rgba(80, 150, 255, 0.3);
  --nx-mark-model-line: rgba(80, 150, 255, 0.9);
  --nx-mark-search: rgba(255, 140, 0, 0.28);
  --nx-mark-search-active: rgba(255, 110, 0, 0.5);
  --nx-mark-search-line: rgba(255, 110, 0, 0.8);
  --nx-paper-selection: rgba(0, 90, 255, 0.28);
  --nx-device-black: #000;
  --nx-device-text: #d8d8d0;
  --nx-device-screen: #0e1115;
  --nx-device-metal: linear-gradient(160deg, #3a3c3f 0%, #1b1c1e 38%, #0e0f10 100%);
  --nx-device-metal-android: linear-gradient(160deg, #4a4d50 0%, #232527 40%, #121314 100%);
  --nx-device-shadow: inset 0 0 0 1.5px #55585c, inset 0 0 0 5px #0b0b0c, 0 0 0 1px rgba(0, 0, 0, 0.6), 18px 40px 80px -30px rgba(0, 0, 0, 0.75), 5px 12px 24px -12px rgba(0, 0, 0, 0.5);
  --nx-device-camera: radial-gradient(circle at 40% 38%, #1d2733 0 3px, #000 4px);
  --nx-device-key: #101112;
  --nx-device-key-shadow: inset 0 0 0 2px #45484c, inset 0 2px 6px rgba(0, 0, 0, 0.6);
  --nx-device-earpiece: #050505;
  --nx-device-earpiece-shadow: inset 0 0 0 1px #2c2e30;
  --nx-device-indicator: rgba(255, 255, 255, 0.85);
  --nx-device-indicator-light: rgba(0, 0, 0, 0.8);
  --nx-preview-target-offset: 110px;
  --nx-device-radius: 44px;
  --nx-device-radius-landscape: 38px;
  --nx-device-screen-radius: 30px;
  --nx-ink-on-warm: #1d1405;
  /* Fixed design samples represent the preview's own palette, not shell chrome. */
  --nx-sample-midnight: #0e1115;
  --nx-sample-midnight-accent: #72e2b5;
  --nx-sample-paper: #f1eee6;
  --nx-sample-paper-accent: #2f7c67;
  --nx-sample-warm: #17120f;
  --nx-sample-warm-accent: #e48d5d;

  /* Springs (07 §2 motion): physical curves as CSS linear(), no library.
     snappy = UI feedback, settle = panels and the docked chat, drift = ambient. */
  --nx-spring-snappy: linear(0, 0.058, 0.179, 0.322, 0.446, 0.575, 0.685, 0.774, 0.843, 0.895, 0.933, 0.957, 0.976, 0.988, 0.996, 1.001, 1.003, 1.004, 1.004, 1.003, 1.002, 1.001, 1);
  --nx-spring-settle: linear(0, 0.047, 0.154, 0.287, 0.427, 0.571, 0.686, 0.782, 0.859, 0.917, 0.96, 0.989, 1.008, 1.019, 1.025, 1.026, 1.024, 1.021, 1.018, 1.014, 1.011, 1.008, 1.005, 1.004, 1.002, 1.001, 1);
  --nx-spring-drift: linear(0, 0.04, 0.125, 0.237, 0.35, 0.464, 0.568, 0.654, 0.731, 0.791, 0.843, 0.884, 0.914, 0.939, 0.958, 0.971, 0.981, 0.988, 0.993, 0.996, 0.998, 1);
  --nx-snappy: 220ms;
  --nx-settle: 320ms;
  /* drift = slow fills (progress bars, meters): the slowest a transition may be. */
  --nx-drift: 320ms;

  /* Leaf light, one meaning each (07 §2-3): the sun = something is running
     (amber) or needs you (sunset orange); green is the calm surface and its
     actions. A warning that asks nothing of you is caution: no sun, the
     warning shape carries it. Components use these names, never raw colours. */
  --nx-state-running: var(--nx-amber);
  /* Running as text (labels, counts, timers): the same amber where it reads at
     4.5:1; Morning deepens it to ochre and keeps the bright amber for dots and fills. */
  --nx-state-running-text: var(--nx-state-running);
  --nx-state-needs: var(--nx-gold);
  --nx-state-ok: color-mix(in srgb, var(--nx-green) 70%, transparent);
  --nx-state-error: var(--nx-red);
  --nx-state-caution: var(--nx-text-2);
  --nx-caution-soft: color-mix(in srgb, var(--nx-text) 6%, transparent);
  --nx-caution-line: color-mix(in srgb, var(--nx-text) 22%, transparent);

  /* One sun, top-left (07 §2 "depth, not borders"): every cast shadow falls
     right and down at the same angle (x = 0.45 y). --nx-shade is per theme. */
  --nx-lift-1: 1px 2px 4px -1px var(--nx-shade);
  --nx-lift-2: 5px 11px 30px -18px var(--nx-shade);
  --nx-lift-3: 11px 24px 60px -22px var(--nx-shade);
  /* A panel's edge where it overlaps another: contact shade with no direction. */
  --nx-edge: 0 0 40px -18px var(--nx-shade);

  /* Density (Calm / Workshop / Grove): one data model, three spacings. */
  --nx-row-pad: 7px;
  --nx-row-gap: 2px;
  --nx-strip-h: 28px;
  --nx-dock-w: 380px;

  --nx-sidebar-w: 276px;
  --nx-panel-w: 400px;
  --nx-canopy-w: 292px;
  --nx-thread-w: 760px;
  --nx-safe-bottom: env(safe-area-inset-bottom, 0px);
  --nx-safe-top: env(safe-area-inset-top, 0px);

}

/* Re-derive colours on each app window: inherited custom properties otherwise
   resolve against the shell's palette rather than that window's skin. */
:root, .nx, .nx [data-nx-skin] {
  --nx-accent-hover: color-mix(in srgb, var(--nx-accent) 92%, var(--nx-text));
  --nx-accent-press: color-mix(in srgb, var(--nx-accent) 86%, var(--nx-text));
  --nx-on-error: var(--nx-on-accent);
  --nx-on-success: var(--nx-on-accent);
}

.nx[data-nx-density="calm"] {
  --nx-row-pad: 9px;
  --nx-row-gap: 4px;
  --nx-sidebar-w: 288px;
}

.nx[data-nx-density="grove"] {
  --nx-row-pad: 5px;
  --nx-row-gap: 1px;
  --nx-sidebar-w: 260px;
