      if (Object.keys(patch).length) overrides[id] = { ...patch, ...overrides[id] };
    }
    const projects = { ...current.projects };
    for (const [path, row] of Object.entries(snapshot.projects || {})) projects[path] = { name: row?.name || path, path: row?.path || path };
