.nx .nx-cd-detail h4 { font-size: var(--nx-fs-sm); font-weight: 600; color: var(--nx-text); }
.nx .nx-cd-facts, .nx .nx-cd-receipt dl { display: grid; gap: var(--nx-space-4); margin: 0; font-size: var(--nx-fs-sm); }
.nx .nx-cd-facts > div, .nx .nx-cd-receipt dl > div { display: grid; grid-template-columns: 64px minmax(0, 1fr); gap: var(--nx-space-8); }
.nx .nx-cd-facts dt, .nx .nx-cd-receipt dt { color: var(--nx-muted); }
.nx .nx-cd-facts dd, .nx .nx-cd-receipt dd { margin: 0; color: var(--nx-text-2); overflow-wrap: anywhere; }
.nx .nx-cd-detail .is-mono, .nx .nx-cd-muted .is-mono { font-family: var(--nx-mono); font-size: var(--nx-fs-xs); }
.nx .nx-cd-receipt { display: grid; gap: var(--nx-space-8); }
.nx .nx-cd-receipt > .nx-btn { justify-self: start; }
.nx .nx-cd-reply { margin: 0; max-height: 220px; padding: var(--nx-space-8) var(--nx-space-10); border-radius: var(--nx-r); background: var(--nx-raised-2); font-family: var(--nx-mono); font-size: var(--nx-fs-xs); line-height: 1.5; color: var(--nx-text-2); white-space: pre-wrap; overflow-wrap: anywhere; }
.nx .nx-cd-prompt { font-size: var(--nx-fs-sm); line-height: 1.5; color: var(--nx-text-2); white-space: pre-wrap; overflow-wrap: anywhere; }
.nx .nx-cd-needs { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: var(--nx-space-8) var(--nx-space-10); padding: var(--nx-space-10); border-radius: var(--nx-r); background: var(--nx-gold-soft); font-size: var(--nx-fs-sm); color: var(--nx-text); }
.nx .nx-cd-needs > .nx-icon { color: var(--nx-state-needs); margin-top: var(--nx-space-1); }
.nx .nx-cd-needs > .nx-btn { grid-column: 2; justify-self: start; }
.nx .nx-cd-checks { display: grid; gap: var(--nx-space-8); margin: 0; padding: 0; list-style: none; font-size: var(--nx-fs-sm); color: var(--nx-text-2); }
.nx .nx-cd-checks li { display: flex; gap: var(--nx-space-7); align-items: flex-start; }
.nx .nx-cd-checks li > span { display: grid; gap: var(--nx-space-3); min-width: 0; overflow-wrap: anywhere; }
.nx .nx-cd-checks small { font-size: var(--nx-fs-xs); color: var(--nx-muted); line-height: 1.45; }
.nx .nx-cd-checks .nx-icon { margin-top: var(--nx-space-2); flex: none; color: var(--nx-muted); }
.nx .nx-cd-checks .is-ok .nx-icon { color: var(--nx-state-ok); }
.nx .nx-cd-checks .is-bad .nx-icon { color: var(--nx-state-error); }
.nx .nx-cd-turns { display: grid; gap: var(--nx-space-2); margin: 0; padding: 0; list-style: none; }
.nx .nx-cd-turns button { width: 100%; display: grid; grid-template-columns: auto minmax(0, 1fr); gap: var(--nx-space-2) var(--nx-space-8); align-items: center; padding: var(--nx-space-6) var(--nx-space-8); border-radius: var(--nx-r-sm); text-align: left; font-size: var(--nx-fs-sm); color: var(--nx-text-2); }
.nx .nx-cd-turns button:hover:not(:disabled) { background: var(--nx-hover); }
.nx .nx-cd-turns small { grid-column: 2; font-size: var(--nx-fs-xs); color: var(--nx-muted); font-variant-numeric: tabular-nums; }
.nx .nx-cd-muted { display: flex; align-items: center; gap: var(--nx-space-6); flex-wrap: wrap; font-size: var(--nx-fs-xs); color: var(--nx-muted); line-height: 1.5; }
.nx .nx-cd-hint { margin-top: auto; font-size: var(--nx-fs-xs); color: var(--nx-muted); }
.nx .nx-cd-ok { display: inline-flex; align-items: center; gap: var(--nx-space-4); font-size: var(--nx-fs-xs); color: var(--nx-state-ok); }

.nx .nx-cd-input { width: 100%; min-width: 0; padding: var(--nx-space-6) var(--nx-space-10); border-radius: var(--nx-r-sm); background: var(--nx-raised-2); color: var(--nx-text); box-shadow: inset 0 0 0 var(--nx-stroke) var(--nx-line-strong); font-size: var(--nx-fs); line-height: 1.45; resize: vertical; }
.nx .nx-cd-input:focus-visible { box-shadow: inset 0 0 0 var(--nx-stroke-icon) var(--nx-accent-hi); }
.nx .nx-cd-input.is-mono { font-family: var(--nx-mono); font-size: var(--nx-fs-sm); }
.nx .nx-cd-new { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; gap: var(--nx-space-12); padding: var(--nx-space-16) var(--nx-space-18) var(--nx-space-24); max-width: 820px; }
.nx .nx-cd-new h2 { font-size: var(--nx-fs-xl); font-weight: 600; color: var(--nx-text); }
.nx .nx-cd-lead { font-size: var(--nx-fs-sm); color: var(--nx-text-2); line-height: 1.5; }
.nx .nx-cd-field { display: grid; gap: var(--nx-space-5); font-size: var(--nx-fs-sm); color: var(--nx-muted); }
.nx .nx-cd-field.is-narrow { max-width: 200px; }
.nx .nx-cd-problems { margin: 0; padding-left: var(--nx-space-18); color: var(--nx-state-caution); font-size: var(--nx-fs-sm); }
.nx .nx-cd-new-foot { display: flex; align-items: center; gap: var(--nx-space-8); }

.nx .nx-cd-routes { display: grid; gap: var(--nx-space-10); padding: var(--nx-space-12); border-radius: var(--nx-r-lg); background: var(--nx-raised); box-shadow: var(--nx-card-shadow); }
.nx .nx-cd-routes > header { display: grid; gap: var(--nx-space-2); }
.nx .nx-cd-routes h3 { font-size: var(--nx-fs-md); font-weight: 600; color: var(--nx-text); }
.nx .nx-cd-routes > header p { font-size: var(--nx-fs-xs); color: var(--nx-muted); }
.nx .nx-cd-route { display: grid; grid-template-columns: minmax(0, 190px) minmax(0, 1fr); gap: var(--nx-space-4) var(--nx-space-12); align-items: center; padding-top: var(--nx-space-8); box-shadow: inset 0 var(--nx-stroke) 0 var(--nx-line); }
.nx .nx-cd-route-name { display: grid; gap: var(--nx-space-1); min-width: 0; }
.nx .nx-cd-route-name strong { font-weight: 500; color: var(--nx-text); }
.nx .nx-cd-route-name span { font-size: var(--nx-fs-xs); color: var(--nx-muted); line-height: 1.4; }
.nx .nx-cd-route-pick { display: flex; flex-wrap: wrap; align-items: center; gap: var(--nx-space-6); min-width: 0; }
.nx .nx-cd-route-pick .nx-cd-input { width: auto; flex: 1 1 150px; }
.nx .nx-cd-route-pick .nx-cd-input.is-short { flex: 1 1 120px; }
.nx .nx-cd-route .nx-cd-error { grid-column: 1 / -1; }
.nx .nx-cd-routes-pop { padding: var(--nx-space-12) var(--nx-space-18) 0; }

@container (max-width: 760px) {
  .nx .nx-cd-view { overflow: auto; }
  .nx .nx-cd-body { flex: none; flex-direction: column; }
  .nx .nx-cd-tree { flex: none; }
  .nx .nx-cd-detail { flex-basis: auto; }
  .nx .nx-cd-route { grid-template-columns: minmax(0, 1fr); }
}
.nx.is-phone .nx-cd { flex-direction: column; }
.nx.is-phone .nx-cd-list { flex-basis: auto; max-height: 34vh; box-shadow: inset 0 calc(-1 * var(--nx-stroke)) 0 var(--nx-line); }
.nx.is-phone .nx-cd-view, .nx.is-phone .nx-cd-new { padding-left: var(--nx-space-16); padding-right: var(--nx-space-16); }
.nx.is-phone .nx-cd-body { flex-direction: column; overflow: auto; }
.nx.is-phone .nx-cd-tree { flex-direction: column; align-items: stretch; overflow: visible; }
.nx.is-phone .nx-cd-level { flex-basis: auto; }
.nx.is-phone .nx-cd-detail { flex-basis: auto; }
.nx.is-phone .nx-cd-input { font-size: var(--nx-fs-lg); }
@media (max-width: 640px) { .nx .nx-cd-route { grid-template-columns: minmax(0, 1fr); } }

/* The four themes of the control UI. Each is only colour; spacing, type and
   motion live in nxTokens.css. Components use the names, never raw colours.

   Forest  (dark)    late evening under the trees: near-black greens, cream text,
                     leaf-green actions, the sun only where something happens.
   Morning (light)   first sun through the canopy on warm paper: moss-shaded
                     sidebar, lit cards that cast forest shade, deep leaf greens.
   Sunset  (sunset)  twilight: a cool violet sky over a warm horizon,
                     sunset-orange actions, gold for what needs you.
   Night Green (night) dark water: deep blue-green, sea-green actions,
                     light from the surface above, glowing specks below.

   In every theme the sun means something is happening: --nx-amber = running,
   --nx-gold = needs you. Nothing else is painted with them (15 · T2): actions
   are the theme's accent, warnings that ask nothing are caution (nxTokens).

   Light: one low sun, top-left. --nx-ambient is the still leaf light any
   surface may use; --nx-ambient-sun and --nx-dapple are the sunlight the
   shell's ambient layer adds only while something runs (nxMotion.css).
   --nx-shade is the colour every cast shadow (--nx-lift-*) uses.

   Every text colour (--nx-muted, --nx-faint, and gold/red/green where they are
   text) reads at 4.5:1 or better on every surface of its theme, hover rows
   included (WCAG AA; checked by web/a11y/nx-a11y-audit.mjs). */

:root,
.nx,
.nx[data-nx-theme="dark"] {
  /* Forest (reworked in the Look track): a deep green night, not grey-black.
     Surfaces step up in green-tinted layers (sidebar < page < panel < card <
     selected), lines are cool leaf-white instead of cream so edges read
     crisp, and the leaf accent is brighter and more saturated so actions
     stand out. Text is a clean green-white; every text colour keeps 4.5:1 on
     every surface and hover state (checked by nxLookModel.test.js). */
  --nx-bg: #0d1612;
  --nx-sidebar: #0a120e;
  --nx-panel: #111c17;
  --nx-raised: #15221b;
  --nx-raised-2: #1b2b23;
  --nx-hover: rgba(214, 240, 222, 0.05);
  --nx-active: rgba(214, 240, 222, 0.09);
  --nx-line: rgba(214, 240, 222, 0.08);
  --nx-line-strong: rgba(214, 240, 222, 0.15);

  --nx-text: #edf2ea;
  --nx-text-2: #cbd7cd;
  --nx-muted: #a5b6a9;
  --nx-faint: #96a99b;

  --nx-accent: #46b077;
  --nx-on-accent: #03140b; /* text on an --nx-accent fill, 4.5:1 or better */
  --nx-accent-hi: #63c98f;
  --nx-accent-text: #95dfb3;
  --nx-accent-soft: rgba(99, 201, 143, 0.14);
  --nx-amber: #f4b847;
  --nx-gold: #f39a3d;
  --nx-gold-soft: rgba(243, 154, 61, 0.14);
  --nx-green: #74d29c;
  --nx-green-soft: rgba(116, 210, 156, 0.12);
  --nx-red: #f48a7a;
  --nx-red-soft: rgba(244, 138, 122, 0.12);
  --nx-sun: linear-gradient(180deg, #ffc455 0%, #f58a2e 55%, #e3582a 100%);
  --nx-sun-ink: #2a1406;

  --nx-focus: 0 0 0 var(--nx-stroke-strong) var(--nx-bg), 0 0 0 var(--nx-halo) var(--nx-focus-ring);
  --nx-focus-ring: #63c98f;
  --nx-shade: rgba(0, 6, 3, 0.62);
  --nx-shadow-pop: 0 0 0 1px var(--nx-line-strong), inset 0 1px 0 rgba(214, 240, 222, 0.05), 8px 18px 48px -12px rgba(0, 6, 3, 0.75), 1px 2px 6px rgba(0, 6, 3, 0.4);
  --nx-card-shadow: 0 0 0 1px var(--nx-line), inset 0 1px 0 rgba(214, 240, 222, 0.04), 6px 14px 30px -20px rgba(0, 6, 3, 0.8);
  --nx-selection: rgba(99, 201, 143, 0.3);
  --nx-scrollbar: rgba(214, 240, 222, 0.16);
  --nx-state-stale: #8a7560;
  --nx-scrim: rgba(2, 8, 5, 0.6);
  /* Leaf light: a soft green glow through the canopy top-right and moss light
     pooled bottom-left; the low sun top-left only while something runs. */
  --nx-ambient:
    radial-gradient(1200px 560px at 78% -16%, rgba(78, 186, 128, 0.16), transparent 64%),
    radial-gradient(900px 520px at -4% 108%, rgba(46, 130, 88, 0.12), transparent 62%),
    radial-gradient(700px 360px at 4% -10%, rgba(244, 184, 71, 0.035), transparent 70%);
  --nx-ambient-sun: radial-gradient(900px 460px at 8% -14%, rgba(244, 184, 71, 0.075), transparent 64%);
  /* Round patches of sun on the forest floor (07 §2 komorebi): each leaf gap is a pinhole. */
  --nx-dapple:
    radial-gradient(70px 46px at 20% 16%, rgba(244, 196, 102, 0.075), transparent 70%),
    radial-gradient(44px 30px at 29% 24%, rgba(244, 196, 102, 0.065), transparent 70%),
    radial-gradient(110px 70px at 10% 30%, rgba(244, 184, 71, 0.05), transparent 70%),
    radial-gradient(56px 38px at 38% 11%, rgba(244, 196, 102, 0.05), transparent 70%),
    radial-gradient(36px 24px at 16% 40%, rgba(244, 196, 102, 0.06), transparent 70%);
  color-scheme: dark;
}

/* Forest depth: the sidebar is the shaded forest edge with a little canopy light
   at the top; cards are a step lighter with a faint lit top edge. */
.nx[data-nx-theme="dark"] .nx-side { background: linear-gradient(180deg, color-mix(in srgb, var(--nx-sidebar) 92%, var(--nx-text)) 0%, var(--nx-sidebar) 45%, color-mix(in srgb, var(--nx-sidebar) 85%, var(--nx-bg)) 100%); }
.nx[data-nx-theme="dark"] .nx-widget { background: linear-gradient(180deg, color-mix(in srgb, var(--nx-raised) 97%, var(--nx-text)) 0%, var(--nx-raised) 100%); box-shadow: var(--nx-card-shadow); }
.nx[data-nx-theme="dark"] .nx-composer { background: var(--nx-raised); }
/* Let the canopy light through: the chat column was an opaque sheet over the ambient layer. */
.nx[data-nx-theme="dark"] .nx-work-chat { background: transparent; }

.nx[data-nx-theme="light"] {
  /* Morning: first sun through the canopy onto warm paper (plan 19 R3). The low
     sun sits top-left, so whatever is closer to you is brighter, catches light on
     its top edge and casts a soft shadow down and right. Shade is the forest's:
     green-grey, never brown. Back to front: the sidebar is the forest edge (moss
     paper), the page is paper, panels and cards are lit paper, a selected or
     lifted control is the brightest thing. Warmth stays rare: amber/gold for
     running and needs-you, the sun bloom only while something runs. */
  --nx-bg: #f5f1e6;
  --nx-sidebar: #ebe9da;
  --nx-panel: #faf7f0;
  --nx-raised: #fffdf9;
  --nx-raised-2: #ffffff;
  --nx-hover: rgba(42, 58, 34, 0.055);
  --nx-active: rgba(42, 58, 34, 0.09);
  --nx-line: rgba(42, 54, 32, 0.11);
  --nx-line-strong: rgba(42, 54, 32, 0.2);

  --nx-text: #17221a;
  --nx-text-2: #323f30;
  --nx-muted: #465143;
  --nx-faint: #555d4f;

  --nx-accent: #3a774b;
  --nx-on-accent: #ffffff; /* text on an --nx-accent fill, 4.5:1 or better */
  --nx-accent-hi: #4a8f5d;
  --nx-accent-text: #245a35;
  --nx-accent-soft: rgba(58, 119, 75, 0.11);
  /* The sun stays bright where it is a mark (tree sun, spinner, dots); as text
     it is the deeper ochre below, which reads at 4.5:1 on every Morning surface. */
  --nx-amber: #d4930f;
  --nx-state-running-text: #7a4f08;
  --nx-gold: #8f480b;
  --nx-gold-soft: rgba(232, 137, 43, 0.15);
  --nx-green: #226640;
  --nx-green-soft: rgba(47, 138, 85, 0.1);
  --nx-red: #a1372d;
  --nx-red-soft: rgba(196, 69, 58, 0.1);

  --nx-focus: 0 0 0 var(--nx-stroke-strong) var(--nx-bg), 0 0 0 var(--nx-halo) var(--nx-focus-ring);
  --nx-focus-ring: #2f7d4f;
  /* Forest shade: every cast shadow (--nx-lift-*) uses it. */
  --nx-shade: rgba(30, 50, 28, 0.2);
  /* Lit paper: a ring, sunlight on the top edge, a short contact shadow and a
     soft cast shadow down-right (x = 0.45 y, like --nx-lift-*). */
  --nx-card-shadow: 0 0 0 1px var(--nx-line), inset 0 1px 0 rgba(255, 255, 255, 0.9), 1px 2px 3px -1px rgba(30, 50, 28, 0.1), 7px 15px 30px -18px rgba(30, 50, 28, 0.26);
  --nx-shadow-pop: 0 0 0 1px var(--nx-line-strong), inset 0 1px 0 rgba(255, 255, 255, 0.9), 9px 20px 48px -14px rgba(26, 44, 26, 0.3), 1px 2px 6px rgba(26, 44, 26, 0.08);
  --nx-selection: rgba(58, 119, 75, 0.22);
  --nx-scrollbar: rgba(42, 54, 32, 0.22);
  --nx-state-stale: #7d6a52;
  /* Overlays dim the page like a cloud over the trees: cool green-grey, not khaki. */
  --nx-scrim: rgba(26, 40, 28, 0.22);
  /* Still: leaf light pooled bottom-right and a little canopy shade along the top. */
  --nx-ambient:
    radial-gradient(1100px 620px at 104% 110%, rgba(58, 119, 75, 0.13), transparent 62%),
    radial-gradient(1400px 260px at 60% -10%, rgba(42, 74, 40, 0.05), transparent 70%);
  /* Running: the low morning sun warms the top-left. */
  --nx-ambient-sun:
    radial-gradient(1000px 560px at -4% -14%, rgba(255, 190, 80, 0.2), transparent 60%),
    radial-gradient(520px 300px at 6% -6%, rgba(255, 214, 140, 0.16), transparent 70%);
  /* Komorebi by day: small warm sun flecks where the leaves part. (Leaf-shade
     blobs were tried and band into grey rings on paper, so the shade stays out.) */
  --nx-dapple:
    radial-gradient(34px 22px at 22% 18%, rgba(255, 200, 100, 0.24), transparent 72%),
    radial-gradient(22px 15px at 13% 27%, rgba(255, 206, 110, 0.2), transparent 72%),
    radial-gradient(28px 18px at 34% 12%, rgba(255, 214, 130, 0.18), transparent 72%),
    radial-gradient(18px 12px at 29% 30%, rgba(255, 206, 110, 0.16), transparent 72%),
    radial-gradient(40px 26px at 8% 12%, rgba(255, 210, 120, 0.16), transparent 72%);
  color-scheme: light;
}

/* Morning depth (plan 19 R3). In the dark themes a nested surface is lighter, so
   it reads as closer; on paper there is little room above white, so Morning lifts
   with light and shadow instead: the sidebar is the shaded forest edge, the page
   paper, cards lit paper with a cast shadow, and a selected row or control rises
   into the light rather than sinking into a darker stone. */
.nx[data-nx-theme="light"] .nx-side {
  background:
    radial-gradient(360px 220px at -8% -6%, color-mix(in srgb, var(--nx-accent) 22%, transparent), transparent 70%),
    linear-gradient(180deg, var(--nx-raised) 0%, var(--nx-sidebar) 40%, var(--nx-raised) 100%);
  box-shadow: inset calc(-1 * var(--nx-stroke)) 0 0 color-mix(in srgb, var(--nx-line) 55%, transparent);
}
.nx[data-nx-theme="light"] .nx-row.is-active,
.nx[data-nx-theme="light"] .nx-kid-row.is-active,
.nx[data-nx-theme="light"] .nx-rail-chat.is-active,
.nx[data-nx-theme="light"] .nx-onb-rail-step.is-on {
  background: var(--nx-raised-2);
  box-shadow: 0 0 0 var(--nx-stroke) var(--nx-line), var(--nx-lift-1);
}
.nx[data-nx-theme="light"] .nx-seg { background: color-mix(in srgb, var(--nx-text) 6%, transparent); }
.nx[data-nx-theme="light"] .nx-widget { background: var(--nx-panel); }
.nx[data-nx-theme="light"] .nx-continue-card {
  background: linear-gradient(160deg, var(--nx-raised) 30%, color-mix(in srgb, var(--nx-accent) 6%, var(--nx-raised)));
  box-shadow: var(--nx-card-shadow);
}
.nx[data-nx-theme="light"] .nx-continue-card:hover {
  box-shadow: 0 0 0 var(--nx-stroke) color-mix(in srgb, var(--nx-accent-hi) 45%, transparent), inset 0 var(--nx-stroke) 0 var(--nx-line-strong), var(--nx-lift-2);
}
.nx[data-nx-theme="light"] .nx-composer { background: var(--nx-raised-2); }
/* Cards you pick (launcher tiles, setup choices, Canopy cards) are lit paper that
   rises on hover, not a grey stone sunk into the page; their icon wells are leaf. */
.nx[data-nx-theme="light"] .nx-launcher-body { background: var(--nx-panel); }
.nx[data-nx-theme="light"] .nx-tile,
.nx[data-nx-theme="light"] .nx-onb-pick,
.nx[data-nx-theme="light"] .nx-canopy-card { background: var(--nx-raised-2); box-shadow: var(--nx-card-shadow); }
.nx[data-nx-theme="light"] .nx-tile:hover:not(:disabled),
.nx[data-nx-theme="light"] .nx-tile:focus-visible,
.nx[data-nx-theme="light"] .nx-onb-pick:hover {
  background: var(--nx-raised-2);
  box-shadow: 0 0 0 var(--nx-stroke) var(--nx-line-strong), inset 0 var(--nx-stroke) 0 var(--nx-line-strong), var(--nx-lift-2);
}
.nx[data-nx-theme="light"] .nx-tile-icon { color: var(--nx-accent-text); background: var(--nx-accent-soft); }
/* Let the ambient layer through: the chat column is otherwise an opaque sheet of
   --nx-bg over it (.nx-main already paints the same colour underneath). */
.nx[data-nx-theme="light"] .nx-work-chat { background: transparent; }

.nx[data-nx-theme="sunset"] {
  /* Twilight: a cool violet sky over a warm horizon. The surfaces are the sky
     (indigo-violet), so the sun colours stay rare and bright: orange for the
     one primary action, gold for what needs you. */
  --nx-bg: #141020;
  --nx-sidebar: #110d1b;
  --nx-panel: #181325;
  --nx-raised: #201a30;
  --nx-raised-2: #29213b;
  --nx-hover: rgba(236, 222, 255, 0.05);
  --nx-active: rgba(236, 222, 255, 0.09);
  --nx-line: rgba(236, 222, 255, 0.08);
  --nx-line-strong: rgba(236, 222, 255, 0.15);

  --nx-text: #fbf1ea;
  --nx-text-2: #e2d4d8;
  --nx-muted: #a99cb4;
  --nx-faint: #9790a3;

  --nx-accent: #ff7a3d;
  --nx-on-accent: #2a1406; /* text on an --nx-accent fill, 4.5:1 or better */
  --nx-accent-hi: #ff9a5e;
  --nx-accent-text: #ffb488;
  --nx-accent-soft: rgba(255, 122, 61, 0.14);
  --nx-amber: #ffc857;
  --nx-gold: #ffcf66;
  --nx-gold-soft: rgba(255, 207, 102, 0.12);
  --nx-green: #8fd8ae;
  --nx-green-soft: rgba(143, 216, 174, 0.12);
  --nx-red: #ff8088;
  --nx-red-soft: rgba(255, 128, 136, 0.13);
  --nx-sun: linear-gradient(180deg, #ffd56a 0%, #ff8a3d 52%, #ec4b4b 100%);
  --nx-sun-ink: #2a0d08;
  --nx-on-accent: #2a0d08; /* dark ink on the orange accent (white would be under 3:1) */

  --nx-focus: 0 0 0 var(--nx-stroke-strong) var(--nx-bg), 0 0 0 var(--nx-halo) var(--nx-focus-ring);
  --nx-focus-ring: #ff9a5e;
  --nx-shade: rgba(4, 2, 12, 0.66);
  --nx-shadow-pop: 0 0 0 1px var(--nx-line-strong), 8px 18px 48px -12px rgba(4, 2, 12, 0.8), 1px 2px 6px rgba(4, 2, 12, 0.45);
  --nx-card-shadow: 0 0 0 1px var(--nx-line), 6px 14px 30px -20px rgba(4, 2, 12, 0.9);
  --nx-selection: rgba(255, 122, 61, 0.3);
  --nx-scrollbar: rgba(236, 222, 255, 0.16);
  --nx-state-stale: #9a8a9e;
  --nx-scrim: rgba(6, 4, 14, 0.62);
  /* Deep violet overhead, a rose band, and the last of the sun on the horizon. */
  --nx-ambient:
    radial-gradient(1400px 520px at 50% 118%, rgba(255, 138, 61, 0.34), rgba(236, 75, 110, 0.16) 38%, transparent 70%),
    linear-gradient(180deg, rgba(58, 38, 112, 0.42) 0%, rgba(20, 16, 32, 0) 52%);
  --nx-ambient-sun:
    radial-gradient(900px 420px at 8% -14%, rgba(255, 200, 87, 0.1), transparent 64%),
    radial-gradient(900px 380px at 85% 108%, rgba(255, 200, 87, 0.12), transparent 65%);
  /* The first stars instead of leaf light; they stay out while idle (no sun in them). */
  --nx-dapple-still: 1;
  --nx-dapple:
    radial-gradient(2px 2px at 18% 12%, rgba(255, 244, 230, 0.55), transparent 100%),
    radial-gradient(1.5px 1.5px at 72% 8%, rgba(255, 244, 230, 0.45), transparent 100%),
    radial-gradient(2px 2px at 86% 22%, rgba(255, 244, 230, 0.4), transparent 100%),
    radial-gradient(1.5px 1.5px at 41% 18%, rgba(255, 244, 230, 0.35), transparent 100%),
    radial-gradient(1.5px 1.5px at 60% 28%, rgba(255, 244, 230, 0.3), transparent 100%);
  color-scheme: dark;
}

/* Sunset cards let the sky through a little; the sidebar holds the dusk gradient. */
.nx[data-nx-theme="sunset"] .nx-widget { background: color-mix(in srgb, var(--nx-raised) 82%, transparent); backdrop-filter: blur(12px); }
.nx[data-nx-theme="sunset"] .nx-side { background: linear-gradient(180deg, var(--nx-bg) 0%, var(--nx-sidebar) 50%, var(--nx-bg) 100%); }

.nx[data-nx-theme="night"] {
  /* Night Green: dark water. Deep blue-green surfaces like a lake at night,
     sea-green actions, light falling from the surface above and a few glowing
     specks in the depths. Amber and gold still mean running / needs you. */
  --nx-bg: #05141a;
  --nx-sidebar: #041017;
  --nx-panel: #081b22;
  --nx-raised: #0c242c;
  --nx-raised-2: #122f38;
  --nx-hover: rgba(190, 240, 250, 0.05);
  --nx-active: rgba(190, 240, 250, 0.09);
  --nx-line: rgba(190, 240, 250, 0.08);
  --nx-line-strong: rgba(190, 240, 250, 0.15);

  --nx-text: #e2f1ef;
  --nx-text-2: #b5cfcd;
  --nx-muted: #93aeb1;
  --nx-faint: #8b9fa3;

  --nx-accent: #1aa98a;
  --nx-on-accent: #02201a; /* text on an --nx-accent fill, 4.5:1 or better */
  --nx-accent-hi: #36d0a8;
  --nx-accent-text: #8aead2;
  --nx-accent-soft: rgba(54, 208, 168, 0.14);
  --nx-amber: #f0c552;
  --nx-gold: #f7a94b;
  --nx-gold-soft: rgba(247, 169, 75, 0.13);
  --nx-green: #5fdcab;
  --nx-green-soft: rgba(95, 220, 171, 0.12);
  --nx-red: #ff7d70;
  --nx-red-soft: rgba(255, 125, 112, 0.13);
  --nx-sun: linear-gradient(180deg, #ffc455 0%, #f58a2e 55%, #e3582a 100%);
  --nx-sun-ink: #2a1406;

  --nx-focus: 0 0 0 var(--nx-stroke-strong) var(--nx-bg), 0 0 0 var(--nx-halo) var(--nx-focus-ring);
  --nx-focus-ring: #36d0a8;
  --nx-shade: rgba(0, 4, 8, 0.66);
  --nx-shadow-pop: 0 0 0 1px var(--nx-line-strong), 8px 18px 48px -12px rgba(0, 4, 8, 0.8), 1px 2px 6px rgba(0, 4, 8, 0.45);
  --nx-card-shadow: 0 0 0 1px var(--nx-line), 6px 14px 30px -20px rgba(0, 4, 8, 0.9);
  --nx-selection: rgba(54, 208, 168, 0.28);
  --nx-scrollbar: rgba(190, 240, 250, 0.15);
  --nx-state-stale: #6f8b90;
  --nx-scrim: rgba(1, 6, 9, 0.62);
  /* Light through the water from above, blue on one side and green on the other; green weed light below. */
  --nx-ambient:
    radial-gradient(1100px 380px at 30% -14%, rgba(48, 150, 210, 0.16), transparent 65%),
    radial-gradient(900px 360px at 78% -12%, rgba(40, 200, 160, 0.12), transparent 62%),
    radial-gradient(900px 420px at 8% 114%, rgba(26, 169, 138, 0.1), transparent 62%);
  --nx-ambient-sun: radial-gradient(900px 420px at 8% -14%, rgba(240, 197, 82, 0.07), transparent 64%);
  /* Glowing specks in the depths; they stay lit while idle (no sun in them). */
  --nx-dapple-still: 1;
  --nx-dapple:
    radial-gradient(3px 3px at 22% 72%, rgba(120, 240, 220, 0.5), transparent 100%),
    radial-gradient(2.5px 2.5px at 64% 82%, rgba(120, 220, 250, 0.42), transparent 100%),
    radial-gradient(3px 3px at 81% 64%, rgba(120, 240, 220, 0.38), transparent 100%),
    radial-gradient(2px 2px at 41% 88%, rgba(120, 220, 250, 0.34), transparent 100%),
    radial-gradient(2.5px 2.5px at 12% 90%, rgba(120, 240, 220, 0.3), transparent 100%);
  color-scheme: dark;
}

.nx[data-nx-theme="night"] .nx-side { background: linear-gradient(180deg, var(--nx-bg) 0%, var(--nx-sidebar) 52%, var(--nx-bg) 100%); }
.nx[data-nx-theme="night"] .nx-widget { background: color-mix(in srgb, var(--nx-raised) 86%, transparent); backdrop-filter: blur(10px); }

